INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boat','n.小船；轮船v.划船','bəʊt','bəʊt','noun','["a stone boat;  a gravy boat"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('group','n.组；团体adj.群的；团体的v.聚合','ɡɹuːp','ɡɹuːp','noun','["A group of people gathered in front of the Parliament to demonstrate against the Prime Minister''s proposals.","Did you see the new jazz group?","Nitro is an electron-withdrawing group."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nineteen','num.十九','naɪnˈtiːn','naɪnˈtiːn','numeral','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('party','n.政党，党派；聚会，派对；当事人[复数parties]v.参加社交聚会[过去式partied过去分词partied现在分词partying]','ˈpɑ(ː)ɾi','ˈpɑ(ː)ɾi','noun','["The contract requires that the party of the first part pay the fee.","The green party took 12% of the vote.","The settlers were attacked early next morning by a scouting party."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('marriage','n.结婚；婚姻生活；密切结合，合并','ˈmæɹɪdʒ','ˈmæɹɪdʒ','noun','["You should enter marriage for love.","You are cordially invited to the marriage of James Smith and Jane Doe."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clean','adj.清洁的，干净的；清白的v.使干净adv.完全地n.打扫','kleːn','kleːn','noun','["This place needs a clean."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bottle','n.瓶子；一瓶的容量v.控制；把…装入瓶中','ˈbɑ.təl','ˈbɑ.təl','noun','["Beer is often sold in bottles.","I only drank a bottle of beer.","The baby wants a bottle."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tail','n.尾巴；踪迹；辫子；燕尾服v.尾随；装上尾巴adj.从后面而来的；尾部的','teɪl','teɪl','noun','["Most primates have a tail and fangs.","I''m gonna get me some tail tonight."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('very','adj.恰好是，正是；甚至；十足的；特有的adv.非常，很；完全n.(Very)人名；(英)维里','ˈvɛɹi','ˈvɛɹi','adjective','["He tried his very best.","He proposed marriage in the same restaurant,at the very table where they first met."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bag','n.袋；猎获物；（俚）一瓶啤酒v.猎获；把…装入袋中；占据，私吞；使膨大','ˈbæːɡ','ˈbæːɡ','noun','["Acid House is not my bag: I prefer the more traditional styles of music.","The grounder hit the bag and bounced over the fielder’s head.","He headed back to the bag."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Tuesday','n.星期二','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cancel','v.取消；删去n.取消，撤销','ˈkænsl̩','ˈkænsl̩','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('map','v.映射；计划；绘制地图；确定基因在染色体中的位置n.地图；示意图；染色体图','mæp','mæp','noun','["I don''t want to play this map again!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grandparent','n.祖父母；祖父或祖母；外祖父母；外祖父或外祖母','ˈɡɹæn(d)pæɹənt','ˈɡɹæn(d)pæɹənt','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moon','n.月亮；月球；月光；卫星v.闲荡；出神','muːn','muːn','proper noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('be','v.是；有，存在；做，成为；发生n.(Be)人名；(缅)拜；(日)部(姓)；(朝)培；(中非)贝','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('America','n.美洲（包括北美和南美洲）；美国','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('need','n.需要，要求；缺乏；必要之物v.需要','niːd','niːd','noun','["I''ve always tried to have few needs beyond food,clothing and shelter."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('new','adj.新的，新鲜的；更新的；初见的adv.新近n.(New)人名；(英)纽','njʉː','njʉː','noun','["Out with the old,in with the new."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stamp','n.邮票；印记；标志；跺脚v.铭记；标出；盖章于…；贴邮票于…；用脚踩踏','stæmp','stæmp','noun','["The horse gave two quick stamps and rose up on its hind legs.","My passport has quite a collection of stamps.","She loved to make designs with her collection of stamps."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('without','prep.没有；超过；在…外面adv.户外；在外面；没有或不显示某事物n.外部；外面','wɪθˈʌʊt','wɪθˈʌʊt','adverb','["Being from a large,poor family,he learned to live without."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quick','n.核心；伤口的嫩肉adj.快的；迅速的，敏捷的；灵敏的adv.迅速地，快','kwɪk','kwɪk','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('joke','n.玩笑，笑话；笑柄v.开…的玩笑','dʒəʊk','dʒəʊk','noun','["It was a joke!","The president was a joke."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('table','n.桌子；表格；平地层v.制表；搁置；嵌合adj.桌子的','ˈteɪbəl','ˈteɪbəl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('its','pron.它的n.(Its)人名；(俄)伊茨','ɪts','ɪts','noun','["In the next game,Adam and Tom will be it…","Let''s play it at breaktime.","caught them doing it"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('check','v.检查，核对；制止，抑制；在…上打勾n.<美>支票；制止，抑制；检验，核对','t͡ʃɛk','t͡ʃɛk','noun','["I don''t know if she will be there,but it''s worth a check.","The castle moat should hold the enemy in check.","Place a check by the things you have done."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('giraffe','n.长颈鹿','dʒɪˈɹɑːf','dʒɪˈɹɑːf','noun','["Are you having a giraffe?!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('picture','n.照片，图画；影片；景色；化身v.画；想像；描写','ˈpɪktʃə','ˈpɪktʃə','noun','["There was a picture hanging above the fireplace.","I took a picture of the church.","Casablanca is my all-time favorite picture."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kiss','v.吻；（风等）轻拂n.吻；轻拂','kɪs','kɪs','verb','["His ball kissed the black into the corner pocket."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('several','adj.几个的；各自的pron.几个；数个','ˈsɛv(ə)ɹəl','ˈsɛv(ə)ɹəl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monitor','n.监视器；监听器；监控器；显示屏；班长v.监控','ˈmɒnɨtə','ˈmɒnɨtə','noun','["The camp monitors look after the children during the night,when the teachers are asleep.","The information flashed up on the monitor.","a machine code monitor"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('culture','n.文化，文明；修养；栽培v.[细胞][微]培养（等于cultivate）','ˈkʌlt͡ʃə','ˈkʌlt͡ʃə','noun','["I''m headed to the lab to make sure my cell culture hasn''t died."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('taxi','v.乘出租车；滑行n.出租汽车','ˈtæk.si','ˈtæk.si','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('health','n.健康；卫生；保健；兴旺','hɛlθ','hɛlθ','noun','["Her mental health is really affected by stressful environments.","The directors are concerned about the financial health of the project.","The enemies on this level have a lot of health."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dialogue','n.对话；意见交换vi.对话vt.用对话表达','ˈdaɪəlɑɡ','ˈdaɪəlɑɡ','noun','["Bill and Melinda maintained a dialogue via email over the course of their long-distance relationship.","The movie had great special effects,but the dialogue was lackluster.","A literary historian,she specialized in the dialogues of ancient Greek philosophers."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recent','adj.最近的；近代的','ˈɹiːsənt','ˈɹiːsənt','adjective','["I met three recent graduates at the conference."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ten','num.十个，十n.(Ten)人名；(英)坦恩；(意)泰恩；(柬)登','tɛn','tɛn','noun','["We divided the chocolates into tens to hand out to Hallowe''en visitors.","Can you give me two tens for this twenty?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blue','n.蓝色；[复数]（美国海、陆、空三军穿的）蓝色制服；蓝颜料；[theblue(s)][用作单数或复数]布鲁斯（歌曲）（一种伤感的美国黑人民歌）adj.蓝色的；沮丧的，忧郁的；下流的v.把…染成蓝色；使成蓝色；给…用上蓝剂；用上蓝剂于','bluː','bluː','noun','["The boys in blue marched to the pipers.","His request for leave came out of the blue."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dark','adj.黑暗的，深色的；模糊的；无知的；忧郁的n.黑暗；夜；黄昏；模糊','dɑːk','dɑːk','adjective','["The room was too dark for reading.","my sister''s hair is darker than mine;  her skin grew dark with a suntan","a dark villain;  a dark deed"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('order','n.命令；顺序；规则；[贸易]定单v.命令；整理；定购','ˈɔːdə','ˈɔːdə','noun','["The house is in order; the machinery is out of order.","to preserve order in a community or an assembly","St. Ignatius Loyola founded the Jesuit order in 1537."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('egg','n.蛋；卵子；家伙；鸡蛋v.煽动；怂恿','eɪɡ','eɪɡ','noun','["I also determine the minimal amount of egg required to make good mayonnaise.","Shut up,you egg!","bad egg"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feeling','n.感觉，触觉；感情，情绪；同情adj.有感觉的；有同情心的；富于感情的v.感觉；认为（feel的现在分词）；触摸','ˈfiːlɪŋ','ˈfiːlɪŋ','verb','["Feel my wrath!","It looks like wood,but it feels more like plastic.","I don''t want you back here,ya feel me?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('at','prep.在（表示存在或出现的地点、场所、位置、空间）；以（某种价格、速度等）；向；达；因为；朝；忙于n.阿特（老挝货币基本单位att）；[化]砹（极不稳定放射性元素）abbr.密封的（airtight）；气温（airtemperature）','','','verb','["Cars 2 is the most influential film of all time. Don''t @ me."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('if','conj.（表条件）如果；即使；是否；（表假设）假如n.条件；设想','ɪf','ɪf','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('piece','n.块；件；篇；硬币v.修补；接合；凑合','piːs','piːs','noun','["I’d like another piece of pie.","a piece of machinery","a sixpenny piece"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('he','n.男孩，男人；它（雄性动物）pron.他','hi','hi','noun','["Is your cat a he or a she?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('direct','adj.直接的；直系的；亲身的；恰好的v.管理；指挥；导演；指向adv.直接地；正好；按直系关系','d(a)ɪˈɹɛkt','d(a)ɪˈɹɛkt','verb','["to direct the affairs of a nation or the movements of an army","He directed his question to the room in general.","He directed me to the left-hand road."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rat','n.鼠；卑鄙小人，叛徒v.捕鼠；背叛，告密','ɹæt','ɹæt','noun','["What a rat,leaving us stranded here!","He loved hockey and was a devoted rink rat.","Get your rat out."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brother','n.兄弟；同事；战友int.我的老兄！','ˈbɹɐðɘ(ɹ)','ˈbɹɐðɘ(ɹ)','noun','["I would like to thank the brother who just spoke.","Listen,brother,I don''t know what you want,but I''m not interested."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geography','n.地理；地形','dʒɪˈɒɡɹəfi','dʒɪˈɒɡɹəfi','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advise','v.建议；劝告，忠告；通知；警告','ədˈvaɪz','ədˈvaɪz','verb','["The dentist advised me to brush three times a day.","The dentist advised brushing three times a day.","The lawyer advised me to drop the case,since there was no chance of winning."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('print','n.印刷业；印花布；印刷字体；印章；印记v.印刷；打印；刊载；用印刷体写；在…印花样','pɹɪnt','pɹɪnt','noun','["TV and the internet haven''t killed print.","Write in print using block letters.","The print is too small for me to read."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('festival','n.节日；庆祝，纪念活动；欢乐adj.节日的，喜庆的；快乐的','ˈfɛstəvəl','ˈfɛstəvəl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('along','adv.一起；向前；来到prep.沿着；顺着','əˈlɑŋ','əˈlɑŋ','adverb','["John played the piano and everyone sang along.","Don''t stop here. Just move along."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forest','v.植树于，使成为森林n.森林','ˈfɒɹɪst','ˈfɒɹɪst','noun','["a forest of criticism"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apple','n.苹果，苹果树，苹果似的东西；[美俚]炸弹，手榴弹，（棒球的）球；[美俚]人，家伙。','ˈæp.əl','ˈæp.əl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salad','n.色拉；尤指莴苣','ˈsæləd','ˈsæləd','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rabbit','n.兔子，野兔v.让…见鬼去吧','ˈɹæbət','ˈɹæbət','noun','["The pioneers survived by eating the small game they could get: rabbits,squirrels and occasionally a raccoon."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('we','pron.我们（主格）；笔者，本人（作者或演讲人使用）；朕，寡人n.(We)人名；(缅)韦','wiː','wiː','pronoun','["How are we all tonight?","How are we feeling this morning?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yours','pron.你（们）的东西；你的责任[义务]；你的家属；来信，尊函adj.你（们）的（东西）；信末署名前用语','jɔː(ɹ)z','jɔː(ɹ)z','pronoun','["If this edit is mine,the other must be yours.  Their encyclopedia is good,but yours is even better.  It’s all yours.","Yours sincerely,  Yours faithfully,  Yours,  Sincerely yours,"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shop','n.商店；店铺v.购物','ʃɒp','ʃɒp','noun','["This is where I do my weekly shop."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theirs','pron.他们的；她们的；它们的','ðɛəz','ðɛəz','pronoun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wet','adj.[气象][物]潮湿的；有雨的n.雨天；湿气v.弄湿','wɛt','wɛt','noun','["Don''t go out in the wet."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shout','v.呼喊；喊叫；大声说n.呼喊；呼叫','ʃaʊt','ʃaʊt','noun','["Next up the new single from Beyoncé,but first a shout to Barry Bloggins and his wife Belinda..."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purse','n.(女士)手提袋；(国家、家庭、团体等的)财力v.（嘴巴）皱起，使缩拢；撅嘴','pɜːs','pɜːs','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modern','adj.现代的，近代的；时髦的n.现代人；有思想的人','ˈmɒd(ə)n','ˈmɒd(ə)n','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('express','v.表达；快递adj.明确的；迅速的；专门的n.快车，快递，专使；捷运公司','ɛk.ˈspɹɛs','ɛk.ˈspɹɛs','noun','["I took the express into town."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blackboard','n.黑板','ˈblækbɔːd','ˈblækbɔːd','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('servant','n.仆人，佣人；公务员；雇工','ˈsɜːvənt','ˈsɜːvənt','noun','["There are three servants in the household,the butler and two maids.","She is quite the humble servant,the poor in this city owe much to her but she expects nothing."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hobby','n.嗜好；业余爱好','ˈhɒ.bi','ˈhɒ.bi','noun','["I like to collect stamps from different countries as a hobby."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('winter','n.冬季；年岁；萧条期v.过冬adj.冬天的；越冬的','ˈwɪntɚ','ˈwɪntɚ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plant','n.工厂，车间；植物；设备；庄稼v.种植；培养；栽培；安置','plænt','plænt','noun','["The garden had a couple of trees,and a cluster of colourful plants around the border.","That gun''s not mine! It''s a plant! I''ve never seen it before!"]');
