INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capital','n.首都，省会；资金；大写字母；资本家adj.首都的；重要的；大写的','ˈkæp.ɪ.təl','ˈkæp.ɪ.təl','noun','["He does not have enough capital to start a business.","The Welsh government claims that Cardiff is Europe’s youngest capital.","Interpreters need a good amount of cultural capital in order to function efficiently in the profession."]');
