INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('song','n.歌曲；歌唱；诗歌；鸣声','sɒŋ','sɒŋ','noun','["Thomas listened to his favorite song on the radio yesterday.","I love hearing the song of canary birds.","He bought that car for a song."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('special','n.特使，特派人员；特刊；特色菜；专车；特价商品adj.特别的；专门的，专用的','ˈspɛ.ʃəl','ˈspɛ.ʃəl','noun','["We''re running a special on turkey for Thanksgiving.","Today''s special is our tuna melt on rye.","Did you see the Christmas special?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rope','n.绳，绳索v.捆，绑','ɹəʊp','ɹəʊp','noun','["Nylon rope is usually stronger than similar rope made of plant fibers.","The swinging bridge is constructed of 40 logs and 30 ropes.","The duchess wore a rope of pearls to the soirée."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collect','v.收集；募捐adv.由收件人付款地adj.由收件人付款的n.(Collect)人名；(英)科莱克特','kəˈlɛkt','kəˈlɛkt','verb','["Suzanne collected all the papers she had laid out.","A bank collects a monthly payment on a client''s new car loan.   A mortgage company collects a monthly payment on a house.","I don''t think he collects as much as hoards."]');
