INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centre','v.以…为中心n.中心adj.中央的','ˈsen.tə(ɹ)','ˈsen.tə(ɹ)','noun','["shopping center,convention center,civic center,garment center,Lincoln Center for the Performing Arts,Rockefeller Center","the center of attention"]');
