INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardly','adv.几乎不，简直不；刚刚','ˈhɑːdli','ˈhɑːdli','adverb','["I can''t really deal hardly with people.","they hardly ever watch television;  I hardly think they''ll come in this bad weather;  it''s hardly possible he could lose the election."]');
