INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kid','n.小孩；小山羊v.欺骗；取笑；戏弄adj.小山羊皮制的；较年幼的','kɪd','kɪd','noun','["He treated the oxen like they didn''t exist,but he treated the goat kid like a puppy.","She''s a kid. It''s normal for her to have imaginary friends.","He''s been living in Los Angeles for years now,but he''s a Florida kid."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nearly','adv.差不多，几乎；密切地','ˈniːɹli','ˈniːɹli','adverb','["He left a nearly full beer on the bar."]');
