INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slow','adj.慢的；减速的；迟钝的v.变慢；变萧条adv.慢慢地；迟缓地n.(Slow)人名；(英)斯洛','sləʊ','sləʊ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('any','adj.任何的；所有的；丝毫pron.任何；任何一个；若干adv.稍微；少许n.(Any)人名；(法、罗)阿尼','ˈæni','ˈæni','adverb','["I will not remain here any longer."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('front','n.前面；正面；前线v.面对；朝向；对付adj.前面的；正面的adv.在前面；向前','fɹʌnt','fɹʌnt','noun','["Officially it''s a dry-cleaning shop,but everyone knows it''s a front for the mafia.","He says he likes hip-hop,but I think it''s just a front."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('above','prep.超过；在……上面；在……之上adv.在上面；在上文adj.上文的n.上文','əˈbʌv','əˈbʌv','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smooth','adj.顺利的；光滑的；平稳的v.使光滑；消除（障碍等）；使优雅；缓和n.平滑部分；一块平地adv.光滑地；平稳地；流畅地','smuːð','smuːð','noun','[]');
