INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choice','n.选择；选择权；精选品adj.精选的；仔细推敲的','tʃɔɪs','tʃɔɪs','noun','["Do I have a choice of what color to paint it?","She didn''t leave us much choice.","The ice cream sundae is a popular choice for dessert."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('live','adj.活的；生动的；实况转播的；精力充沛的v.经历；度过n.(Live)人名；(法)利夫','lɪv','lɪv','verb','["He''s not expected to live for more than a few months.","I live at 2a Acacia Avenue.  He lives in LA,but he''s staying here over the summer.","Her memory lives in that song."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('death','n.死；死亡；死神；毁灭','diːθ','diːθ','noun','["The death of my grandmother saddened the whole family.","When death walked in,a chill spread through the room.","England scored a goal at the death to even the score at one all."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('June','n.六月；琼（人名，来源于拉丁语，含义是“年轻气盛的六月”）','','','','[]');
