INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('her','pron.她（she的宾格）；她的（she的所有格）；她（指某个国家；一艘船）n.（法）埃尔（人名）','ə(ɹ)','ə(ɹ)','noun','["I think this bird is a him,but it may be a her."]');
