INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('week','n.周，星期','wiːk','wiːk','noun','["A 4-day week consists of Monday,Tuesday,Wednesday,and Thursday.","I''ll see you Thursday week."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parent','n.父亲（或母亲）；父母亲；根源','ˈpɛəɹənt','ˈpɛəɹənt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cough','n.咳嗽，咳嗽声；咳嗽病v.咳出','kɑf','kɑf','noun','["Behind me,I heard a distinct,dry cough.","Sorry,I can''t come to work today – I''ve got a nasty cough.","He was – cough – indisposed."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gate','n.大门；出入口；门道v.给…装大门','ɡeɪt','ɡeɪt','noun','["The gate in front of the railroad crossing went up after the train had passed.","Singh was bowled through the gate,a very disappointing way for a world-class batsman to get out."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mother','n.母亲；大娘；女修道院院长v.生下；养育；像母亲般关怀或照管adj.母亲的；出生地的','ˈmʌðə(ɹ)','ˈmʌðə(ɹ)','noun','["He had something of his mother in him.","Nutrients and oxygen obtained by the mother are conveyed to the fetus.","The lioness was a mother of four cubs."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voice','n.声音；嗓音；发言权；愿望v.表达；吐露','vɔɪs','vɔɪs','noun','["His low voice allowed him to become a bass in the choir.","to cultivate the voice","The verbal system of Latin has two voices,active and passive."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('important','adj.重要的，重大的；有地位的；有权力的','ɪmˈpɔːtənt','ɪmˈpɔːtənt','adjective','["It is very important to give your daughter independence in her life so she learns from experience."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thick','n.最拥挤部分；活动最多部分；事物的粗大浓密部分adj.厚的；浓的；粗大的adv.密集地；浓浓地，厚厚地','θɪk','θɪk','noun','["It was mayhem in the thick of battle."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tourist','n.旅行者，观光客adj.旅游的vt.在旅行参观vi.旅游；观光adv.坐旅游车厢；坐经济舱','ˈtʊəɹɪst','ˈtʊəɹɪst','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rubbish','n.垃圾，废物；废话adj.毫无价值的','ˈɹʌbɪʃ','ˈɹʌbɪʃ','noun','["The rubbish is collected every Thursday in Gloucester,but on Wednesdays in Cheltenham.","Much of what they sell is rubbish.","Everything the teacher said during that lesson was rubbish. How can she possibly think that a bass viol and a cello are the same thing?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prepare','v.准备；使适合；装备；起草','pɹɪˈpɛə','pɹɪˈpɛə','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('house','n.住宅；家庭；机构；议会；某种用途的建筑物v.覆盖；给…房子住；把…储藏在房内','hʌʊs','hʌʊs','noun','["This is my house and my family''s ancestral home.","On arriving at the zoo,we immediately headed for the monkey house.","After her swan-song,there wasn''t a dry eye in the house."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('through','prep.通过；穿过；凭借adv.彻底；从头至尾adj.直达的；过境的；完结的','θɹuː','θɹuː','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mad','adj.疯狂的；发疯的；愚蠢的；着迷的n.狂怒','ˈmæːd','ˈmæːd','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('queen','n.女王，王后；（纸牌中的）皇后；（蜜蜂等的）蜂王v.使…成为女王或王后','kwiːn','kwiːn','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lake','n.湖；深红色颜料；胭脂红vt.（使）血球溶解vi.（使）血球溶解','leɪk','leɪk','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('math','n.数学（等于mathematics）','mɑːθ','mɑːθ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('home','n.家，住宅；产地；家乡；避难所adv.在家，回家；深入地adj.国内的，家庭的；有效的v.归巢，回家','(h)əʊm','(h)əʊm','noun','["the home of the pine"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('often','adv.常常，时常','ˈɑf(t)ən','ˈɑf(t)ən','adjective','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('box','n.箱，盒子；包厢；一拳v.拳击','bɒks','bɒks','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talk','v.说；谈话；讨论n.谈话；演讲；空谈','toːk','toːk','verb','["Although I don''t speak Chinese I managed to talk with the villagers using signs and gestures.","That''s enough about work,let''s talk holidays!","We talk French sometimes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kitchen','n.厨房；炊具；炊事人员','ˈkɪt͡ʃən','ˈkɪt͡ʃən','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('call','v.呼叫；拜访；叫牌n.电话；呼叫；要求；访问','kɔːɫ','kɔːɫ','noun','["I received several calls today.","I paid a call to a dear friend of mine.","The ship made a call at Southampton."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bee','n.蜜蜂，蜂；勤劳的人','ˈbiː','ˈbiː','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kilo','n.千克','ˈkiːləʊ','ˈkiːləʊ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('period','n.周期，期间；时期；月经；课时；（语法学）句点，句号adj.某一时代的','ˈpɪəɹɪəd','ˈpɪəɹɪəd','noun','["There was a period of confusion following the announcement.","Food rationing continued in the post-war period.","When she is on her period,she prefers not to go swimming."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vegetable','n.蔬菜；植物；植物人adj.蔬菜的；植物的','ˈvɛd͡ʒtəbəl','ˈvɛd͡ʒtəbəl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pull','v.拉；拔；拖n.拉，拉绳；拉力，牵引力；拖','pʊl','pʊl','noun','["He gave the hair a sharp pull and it came out.","She took a pull on her cigarette.","a zipper pull"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glove','n.手套vt.给…戴手套','ɡlʌv','ɡlʌv','noun','["I wore gloves to keep my hands warm.","Frederico had a great glove,but he couldn''t hit a curveball,so he never broke into the pros.","to throw down the glove,i.e. to offer a challenge; to take up the glove,to accept it"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('you','pron.你；你们n.(You)人名；(柬)尤；(东南亚国家华语)猷','jʉː','jʉː','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('March','n.三月','mɑːtʃ','mɑːtʃ','noun','["the march of time"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('examine','v.检查；调查；检测；考试','ɪɡˈzæmɪn','ɪɡˈzæmɪn','verb','["He examined the crime scene for clues.","The doctor examined the patient.","The witness was examined under oath."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('result','n.结果；成绩；答案；比赛结果v.结果；导致；产生','ɹɪˈzʌlt','ɹɪˈzʌlt','noun','["the result of a course of action;  the result of a mathematical operation"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleasure','n.快乐；希望；娱乐；令人高兴的事vt.使高兴；使满意vi.高兴；寻欢作乐','ˈplɛʒə','ˈplɛʒə','noun','["He remembered with pleasure his home and family.","Having a good night''s sleep is one of life''s little pleasures.","What is your pleasure: coffee or tea?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('four','num.四；四个adj.四的；四个的n.(Four)人名；(西)福尔；(法)富尔','foː','foː','noun','["Do you have any more fours? I want to make this a little taller.","I''ll take the threes,fours and fives and go to the playground."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pioneer','n.先锋；拓荒者v.开辟；倡导；提倡','ˌpaɪəˈnɪəɹ','ˌpaɪəˈnɪəɹ','noun','["Certain politicians can be considered as pioneers of reform."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('information','n.信息，资料；知识；情报；通知','ˌɪnfəˈmeɪʃən','ˌɪnfəˈmeɪʃən','noun','["I need some more information about this issue.","For your information,I did this because I wanted to."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('society','n.社会；交往；社团；社交界','səˈsaɪ.ə.ti','səˈsaɪ.ə.ti','noun','["This society has been known for centuries for its colorful clothing and tight-knit family structure.","It was then that they decided to found a society of didgeridoo-playing unicyclists.","The gap between Western and Eastern societies seems to be narrowing."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compare','n.比较v.比拟，喻为；[语]构成','kəmˈpɛə','kəmˈpɛə','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provide','v.提供；规定；准备；装备','pɹəˈvaɪd','pɹəˈvaɪd','verb','["It is difficult to provide for my family working on minimum wage.","Provide against disaster.","I''ll lend you the money,provided that you pay it back by Monday."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('owner','n.[经]所有者；物主','ˈəʊnə','ˈəʊnə','noun','["The police recovered the stolen car and returned it to its owner."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sun','n.太阳v.使晒','sʌn','sʌn','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('always','adv.永远，一直；总是；常常','ˈɔː(l).weɪz','ˈɔː(l).weɪz','adverb','["Airplanes did not always exist as a form of transportation.","In this street,the shops always close during lunchtime.","I thought I could always go back to work."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('way','n.方法；道路；方向；行业；习惯adv.大大地；远远地adj.途中的','weɪ','weɪ','noun','["You''re going about it the wrong way.  He''s known for his quirky ways.  I don''t like the way she looks at me.","When I returned home,I found my house and belongings in a most terrible way.","To walk the Way of the Runes,you must experience the runes as they manifest both in the part of Midgard that lies outside yourself and the worlds within. (Diana Paxson)"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rather','adv.宁可，宁愿；相当int.当然啦（回答问题时用）n.(Rather)人名；(英)拉瑟','ˈɹɑːðə','ˈɹɑːðə','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accept','v.接受；承认；承担；承兑；容纳','ækˈsɛpt','ækˈsɛpt','verb','["The Boy Scouts were going to accept him as a member.","I accept the notion that Christ lived.","I accept your proposal,amendment,or excuse."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cover','v.包括；采访，报导；涉及n.封面，封皮；盖子；掩蔽物;幌子，借口','ˈkʌvə','ˈkʌvə','noun','["The soldiers took cover behind a ruined building.","There''s a $15 cover tonight.","We need to set another cover for the Smith party."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Friday','n.星期五','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cause','n.原因；事业；目标v.引起；使遭受','kɔːz','kɔːz','noun','["They identified a burst pipe as the cause of the flooding.","The end of the war was a cause for celebration."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('visitor','n.访问者，参观者；视察者；候鸟','ˈvɪzɪtə','ˈvɪzɪtə','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('August','adj.威严的；令人敬畏的n.八月（简写为Aug）','ɔːˈɡʌst','ɔːˈɡʌst','adjective','["an august patron of the arts","an august lineage"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('report','n.报告；报道；成绩单v.报告；报导；使报到','ɹəˈpoːt','ɹəˈpoːt','noun','["A report by the telecommunications ministry on the phone network revealed a severe capacity problem."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('borrow','v.借；借用；从其他语言中引入n.(Borrow)人名；(英)博罗','ˈbɔɹoʊ','ˈbɔɹoʊ','noun','["This putt has a big left-to right borrow on it."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sorry','adj.遗憾的；对不起的，抱歉的int.对不起，抱歉（表示委婉的拒绝等）','ˈsɔɹi','ˈsɔɹi','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('town','n.城镇，市镇；市内商业区','taʊn','taʊn','noun','["This town is really dangerous because these youngsters have Beretta handguns.","I''ll be in Yonkers,then I''m driving into town to see the Knicks at the Garden tonight.","Call me when you get to town."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('connect','v.连接；联合；关连','kəˈnɛkt','kəˈnɛkt','verb','["I think this piece connects to that piece over there.","Both roads have the same name,but they don''t connect: they''re on opposite sides of the river,and there''s no bridge there.","The new railroad will connect the northern part of the state to the southern part."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweet','adj.甜的；悦耳的；芳香的；亲切的n.糖果；乐趣；芳香；宝贝','swiːt','swiːt','noun','["Can we see the sweet menu,please?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stone','n.石头；结石；[宝]宝石adj.石的，石制的v.向扔石块；用石头铺','stɐʉn','stɐʉn','noun','["a peach stone","kidney stone"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anyone','pron.任何人；任何一个','ˈæniˌwʌn','ˈæniˌwʌn','pronoun','["Almost anyone can change a light bulb."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('here','adv.在这里；此时int.嘿！；喂！n.这里','hiːɹ','hiːɹ','noun','["An Alzheimer patient''s here may in his mind be anywhere he called home in the time he presently re-lives."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('back','n.后面；背部；靠背；足球等的后卫；书报等的末尾v.支持；后退；背书；下赌注adv.以前；向后地；来回地；上溯；回来；回原处adj.后面的；过去的；拖欠的','bæk','bæk','noun','["Could you please scratch my back?","He sat in the back of the room.","The small boat raced over the backs of the waves."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sugar','n.糖；食糖；甜言蜜语v.加糖于；粉饰','ˈʃʊɡə(ɹ)','ˈʃʊɡə(ɹ)','noun','["He usually has his coffee white with one sugar.","I''ll be with you in a moment,sugar.","I think John has a little bit of sugar in him."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paper','n.纸；论文；文件；报纸adj.纸做的v.用纸糊；用纸包装','ˈpeɪpə','ˈpeɪpə','noun','["a paper of pins,tacks,opium,etc.","cantharides paper"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('country','n.国家，国土；国民；乡下，农村；乡村；故乡adj.祖国的，故乡的；地方的，乡村的；国家的；粗鲁的；乡村音乐的','ˈkɐntɹi','ˈkɐntɹi','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fruit','n.水果；产物v.结果实','fɹuːt','fɹuːt','noun','["His long nights in the office eventually bore fruit when his business boomed and he was given a raise.","the fresh-squeezed fruit juice; a fruit salad; an artificial fruit flavor; a fruit tree; a fruit bat","Blessed art thou amongst women and blessed is the fruit of thy womb."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aunt','n.阿姨；姑妈；伯母；舅妈','ɑ(ː)nt','ɑ(ː)nt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pair','n.一对，一双，一副v.把…组成一对','pɛə(ɹ)','pɛə(ɹ)','noun','["I couldn''t decide which of the pair of designer shirts I preferred,so I bought the pair.","Spouses should make a great pair.","a pair of scissors; two pairs of spectacles; several pairs of jeans"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('busy','adj.忙碌的；热闹的；正被占用的v.使忙于n.(Busy)人名；(匈)布希；(法)比西','ˈbɪzi','ˈbɪzi','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('time','n.时间；时代；次数；节拍；倍数v.计时；测定…的时间；安排…的速度adj.定时的；定期的；分期的','tɑem','tɑem','noun','["Time stops for nobody.   the ebb and flow of time","Let''s synchronize our watches so we''re not on different time.","your car runs three times faster than mine;  that is four times as heavy as this"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('foreign','adj.外国的；外交的；异质的；不相关的','ˈfɒɹən','ˈfɒɹən','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prisoner','n.囚犯，犯人；俘虏；刑事被告','ˈpɹɪzənəɹ','ˈpɹɪzənəɹ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('uncle','n.叔叔；伯父；伯伯；舅父；姨丈；姑父','ˈʌŋ.kəl','ˈʌŋ.kəl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laugh','n.笑；引人发笑的事或人v.笑','laːf','laːf','noun','["His deep laughs boomed through the room.","Your new hat''s an absolute laugh,dude."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('English','adj.英国人的；英国的；英文的n.英语；英国人；英文；英格兰人vt.把…译成英语','ˈɪŋ.ɡlɪʃ','ˈɪŋ.ɡlɪʃ','noun','["You can''t hit it directly,but maybe if you give it some english."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('countryside','n.农村，乡下；乡下的全体居民','ˈkʌn.tɹiˌsaɪd','ˈkʌn.tɹiˌsaɪd','noun','["We live in the Swedish countryside."]');
