INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relax','v.放松，休息；松懈，松弛；变从容；休养','ɹɪˈlæks','ɹɪˈlæks','verb','["to relax a rope or cord","to relax discipline","Amusement relaxes the mind."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('size','n.大小；尺寸adj.一定尺寸的v.依大小排列','saɪz','saɪz','noun','["The size of the building seemed to have increased since I was last there.","I don''t think we have the red one in your size."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chair','n.椅子；讲座；（会议的）主席位；大学教授的职位v.担任（会议的）主席；使…入座；使就任要职','t͡ʃɛə(ɹ)','t͡ʃɛə(ɹ)','noun','["All I need to weather a snowstorm is hot coffee,a warm fire,a good book and a comfortable chair.","My violin teacher used to play first chair with the Boston Pops."]');
