INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('windy','adj.多风的，有风的；腹胀的；吹牛的','ˈwɪndi','ˈwɪndi','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attention','n.注意力；关心；立正！（口令）','əˈtɛn.ʃən','əˈtɛn.ʃən','noun','["Please direct your attention to the following words.","The company will now come to attention."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('believe','v.信任；料想；笃信宗教','bɪˈliːv','bɪˈliːv','verb','["I believe there are faeries.","Why did I ever believe you?","After that night in the church,I believed."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mail','n.邮件；邮政，邮递；盔甲v.邮寄；给…穿盔甲','meɪ̯l','meɪ̯l','noun','["Don''t forget to pick up the mail on your way.","He decided to send his declaration by mail."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('letter','n.信；字母，文字；证书；文学，学问；字面意义v.写字母于','-ɾə(ɹ)','-ɾə(ɹ)','noun','["There are twenty-six letters in the English alphabet.","I wrote a letter to my sister about my life.","Benjamin Franklin was multiskilled – a scientist,politician and a man of letters."]');
