INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gold','n.金，黄金；金色；金币adj.金的，金制的；金色的','ɡɒʊld','ɡɒʊld','noun','["France has won three golds and five silvers."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('engineer','n.工程师；工兵；火车司机v.设计；策划；精明地处理','ˌɛnd͡ʒɪˈnɪə','ˌɛnd͡ʒɪˈnɪə','noun','[]');
