INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('too','adv.太；也；很；还；非常；过度','tuː','tuː','adverb','["There has been a cutback in federal subsidies. Too,rates have been increasing.","She doesn''t talk too much.  I''m not too sure about this.","\"You''re not old enough yet.\"  \"I am,too!\""]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doubt','n.怀疑；疑问；疑惑v.怀疑；不信；恐怕；拿不准','dʌʊt','dʌʊt','noun','["I have doubts about how to convert this code to JavaScript."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outside','adj.外面的，外部的；外来的n.外部；外观adv.在外面，向外面；在室外prep.在…范围之外','','','noun','["He''s repainting the outside of his house.","Her outside was stern,but inside was a heart of gold.","Viewed from the outside,the building seemed unremarkable."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basic','adj.基本的；基础的n.基础；要素','ˈbeɪsɪk','ˈbeɪsɪk','noun','["Rice is a basic for many Asian villagers.","Arithmetic is a basic for the study of mathematics.","The drill sergeants gave him hell in basic."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breath','n.呼吸，气息；一口气，（呼吸的）一次；瞬间，瞬息；微风；迹象；无声音，气音','bɹɛθ','bɹɛθ','noun','["I could hear the breath of the runner behind me.","I took a deep breath and started the test.","I could feel the runner''s breath on my shoulder."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawer','n.抽屉；开票人；出票人；起草者；酒馆侍','dɹɔː(ɹ)','dɹɔː(ɹ)','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('until','conj.在…以前；直到…时prep.在…以前；到…为止','ənˈtɪl','ənˈtɪl','preposition','["If you can wait until after my meeting with her,we''ll talk then.","Keep walking until the second set of traffic lights,then turn left."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passenger','n.旅客；乘客；过路人；碍手碍脚的人','ˈpæsənd͡ʒə','ˈpæsənd͡ʒə','noun','["Somebody in a team who does not do their fair share of the work."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('key','n.（打字机等的）键；关键；钥匙v.键入；锁上；调节…的音调；提供线索adj.关键的','kiː','kiː','noun','["The key to solving this problem is persistence.","The key says that A stands for the accounting department.","Some students cheated by using the answer key."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remember','v.记得；牢记；纪念；代…问好','ɹɪˈmɛmbə','ɹɪˈmɛmbə','verb','["Please remember this formula!","Remember what I''ve said.","Remember to lock the door when you go out."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coast','v.滑行；沿岸航行n.海岸；滑坡','kəʊst','kəʊst','noun','["The rocky coast of Maine has few beaches."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tongue','n.舌头；语言v.舔；斥责；用舌吹','tʌŋ','tʌŋ','noun','["cold tongue with mustard","He was speaking in his native tongue."]');
