INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('speed','v.超速，加速；加速，迅速前行；兴隆n.速度，速率；迅速，快速；昌盛，繁荣','spiːd','spiːd','noun','["How does Usain Bolt run at that speed?","Speed limits provide information to the drivers about the safe speed to travel in average conditions.","We could go to the shore next week,or somewhere else if that''s not your speed."]');
