INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('step','n.步，脚步；步骤；步伐；梯级v.踏，踩；走','stɛp','stɛp','noun','["He improved step by step,or by steps.","The driver must have a clear view of the step in order to prevent accidents.","One step is generally about three feet,but may be more or less."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('umbrella','n.雨伞；保护伞；庇护；伞形结构','ʌmˈbɹɛlə','ʌmˈbɹɛlə','noun','["Quick,grab that umbrella before you get rained on!","The fighters provide a defensive air umbrella over the battle group.","The test facility was established under the umbrella of the company''s quality program."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('college','n.大学；学院；学会','ˈkɒlɪd͡ʒ','ˈkɒlɪd͡ʒ','noun','["College of Cardinals,College of Surgeons","College of Engineering","These should be his college years,but he joined the Army."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('show','v.显示；说明；演出；展出n.显示；表演；炫耀','ʃəʊ','ʃəʊ','noun','["art show;  dog show","radio show;  television show","Let''s catch a show."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clock','n.时钟；计时器v.记录；记时','klɒk','klɒk','noun','["This car has over 300,000 miles on the clock.","I can''t go off to lunch yet: I''m still on the clock."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('volleyball','n.排球','ˈvɒlibɔ(ː)l','ˈvɒlibɔ(ː)l','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invention','n.发明；发明物；虚构；发明才能','ɪnˈvɛnʃən','ɪnˈvɛnʃən','noun','["I''m afraid there was no burglar. It was all the housekeeper''s invention.","The invention of the printing press was probably the most significant innovation of the medieval ages.","It took quite a bit of invention to come up with a plan,but we did it."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('although','conj.尽管；虽然；但是；然而','ɔːlˈðəʊ','ɔːlˈðəʊ','conjunction','["Although it was very muddy,the football game went on.","It was difficult,although not as difficult as we had expected."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coffee','n.咖啡；咖啡豆；咖啡色','ˈkɑ.fi','ˈkɑ.fi','noun','["He did not stay for coffee."]');
