INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('film','n.电影；薄膜；胶卷；轻烟v.在…上覆以薄膜；把…拍成电影','ˈfɪlm̩','ˈfɪlm̩','noun','["a clear plastic film for wrapping food"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('school','n.学校；学院；学派；鱼群v.教育','skuːl','skuːl','noun','["The divers encountered a huge school of mackerel."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('useful','adj.有用的，有益的；有帮助的','ˈjuːsfəl','ˈjuːsfəl','adjective','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dish','n.盘；餐具；一盘食物；外貌有吸引力的人v.盛于碟盘中；分发；使某人的希望破灭；说（某人）的闲话','dɪʃ','dɪʃ','noun','["a dish of stew","a vegetable dish","It''s your turn to wash the dishes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everywhere','adv.到处n.每个地方','ɛv.ɹi.(h)weə(ɹ)','ɛv.ɹi.(h)weə(ɹ)','adverb','["He delivers the mail everywhere on this street.","I''ve looked everywhere in the house and still can''t find my glasses."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glad','adj.高兴的；乐意的；令人高兴的；灿烂美丽的vt.使高兴n.(Glad)人名；(塞、瑞典)格拉德；(英)格莱德；(法、挪)格拉','ɡlæd','ɡlæd','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ninety','n.九十adj.九十的；九十岁的num.九十','ˈnaɪn.ti','ˈnaɪn.ti','numeral','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('composition','n.作文，作曲，作品；[材]构成；合成物；成分','ˌkɒmpəˈzɪʃən','ˌkɒmpəˈzɪʃən','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wing','n.翼；翅膀；飞翔；派别；侧厅，耳房，厢房v.使飞；飞过；空运；增加…速度；装以翼','wɪŋ','wɪŋ','noun','["to take wing","the west wing of the hospital","Tom''s a 4 on the Enneagram,with a 3 wing."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('number','n.数；（杂志等的）期；号码；数字；算术v.计入；总数达到','ˈnʌmbə','ˈnʌmbə','noun','["Zero,one,−1,2.5,and pi are all numbers.","The number 8 is usually made with a single stroke.","The equation e^{i\\pi}+1=0 includes the most important numbers: 1,0,\\pi,i,and e."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('polite','adj.有礼貌的，客气的；文雅的；上流的；优雅的','pəˈlaɪt','pəˈlaɪt','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dismiss','v.解散；解雇；开除；让离开；不予理会、不予考虑','dɪsˈmɪs','dɪsˈmɪs','verb','["The company dismissed me after less than a year.","The soldiers were dismissed after the parade.","He dismissed all thoughts of acting again."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doctor','v.修理；篡改，伪造；为…治病；授以博士学位n.医生；博士','ˈdɒktə','ˈdɒktə','noun','["If you still feel unwell tomorrow,see your doctor.","the doctor of a calico-printing machine,which is a knife to remove superfluous colouring matter"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tired','adj.疲倦的；厌倦的，厌烦的v.疲倦；对…腻烦（tire的过去分词形式）','taɪəd','taɪəd','verb','["I tire of this book."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crayon','n.蜡笔，有色粉笔v.以蜡笔作画，用颜色粉笔画','ˈkɹeɪ.ɒ̃','ˈkɹeɪ.ɒ̃','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interest','n.兴趣，爱好；利息；趣味；同行v.使……感兴趣；引起……的关心；使……参与','ˈɪntəɹɪst','ˈɪntəɹɪst','noun','["Our bank offers borrowers an annual interest of 5%.","He has a lot of interest in vintage cars.","I have business interests in South Africa."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wonderful','adj.极好的，精彩的，绝妙的；奇妙的；美妙；胜；神妙','ˈwʌn.də.fl','ˈwʌn.də.fl','adjective','["They served a wonderful six-course meal."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mine','n.矿，矿藏；矿山，矿井；地雷，水雷v.开采，采掘；在…布雷pron.我的','maɪn','maɪn','pronoun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wind','n.风；呼吸；气味；卷绕v.缠绕；上发条；使弯曲；吹号角；绕住或缠住某人','ˈwaɪnd','ˈwaɪnd','noun','["As they accelerated onto the motorway,the wind tore the plywood off the car''s roof-rack.","the wind of a cannon ball;  the wind of a bellows","After the second lap he was already out of wind."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('one','pron.一个人；任何人adj.一的；唯一的n.一num.一；一个','wan','wan','noun','["I knew as soon I met him that John was the one for me and we were married within a month.","2003 September 26,\"DEAL WITH IT!!!!11one!!\",in alt.games.video.nintendo.gamecube,Usenet"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('arm','n.手臂；武器；袖子；装备；部门v.武装起来','ɑːm','ɑːm','noun','["She stood with her right arm extended and her palm forward to indicate “Stop!”","The arm and forearm are parts of the upper limb in the human body.","the arms of an octopus"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('except','v.不计；把…除外prep.除…之外conj.除了；要不是','ɪkˈsɛpt','ɪkˈsɛpt','verb','["to except to a witness or his testimony"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trust','n.信任，信赖；责任；托拉斯v.信任，信赖；盼望；赊卖给','trʊst','trʊst','noun','["He needs to regain her trust if he is ever going to win her back.","I was out of cash,but the landlady let me have it on trust.","I put the house into my sister''s trust."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('long','n.长时间；[语]长音节；（服装的）长尺寸；长裤adj.长的；过长的；做多头的；长时间的；冗长的，长音v.渴望；热望adv.长期地；始终','ˈlɔːŋ','ˈlɔːŋ','noun','["Every uptick made the longs cheer."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('other','adj.其他的，另外的pron.另外一个','ˈɐðə','ˈɐðə','noun','["I''m afraid little Robbie does not always play well with others.","One boat is not better than the other."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dozen','n.十二个，一打adj.一打的','ˈdʌzən','ˈdʌzən','noun','["Can I have a dozen eggs,please?","There must have been dozens of examples just on the first page."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fear','n.害怕；恐惧；敬畏；担心v.害怕；敬畏；为…担心','fɪə','fɪə','noun','["He was struck by fear on seeing the snake.","Not everybody has the same fears.  I have a fear of ants."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('as','conj.因为；随着；虽然；依照；当…时prep.如同；当作；以…的身份adv.同样地；和…一样的','','','adverb','["It''s not as well made,but it''s twice as expensive.","1865,The Act of Suicide as Distinct from the Crime of Self-Murder: A Sermon"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('before','prep.在…之前，先于adv.以前；在前conj.在…以前；在…之前','bɪˈfɔː','bɪˈfɔː','adverb','["I''ve never done this before."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stream','n.溪流；流动；潮流；光线v.流；涌进；飘扬','stɹiːm','stɹiːm','noun','["He poured the milk in a thin stream from the jug to the glass.","Her constant nagging was to him a stream of abuse.","Haredi Judaism is a stream of Orthodox Judaism characterized by rejection of modern secular culture."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('after','adv.后来，以后prep.在……之后conj.在……之后adj.以后的','ˈæf.tə(ɹ)','ˈæf.tə(ɹ)','adjective','["The after gun is abaft the forward gun."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fix','v.使固定；修理；安装；准备n.困境；方位；贿赂','ˈfɪks','ˈfɪks','noun','["That plumber''s fix is much better than the first one''s.","It rained before we repaired the roof,and were we in a fix!","We have a fix on your position."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behaviour','n.行为；习性；运行状况（=behavior）','bɪˈheɪvjə','bɪˈheɪvjə','noun','["She can''t stop the strange behaviour because she has OCD (obsessive-compulsive disorder)."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('room','n.房间；空间；余地；机会；房间里所有的人v.为…提供住处；租房，合住；投宿，住宿；留…住宿','ɹuːm','ɹuːm','noun','["Go to your room!","The room was on its feet.","Some users may not be able to access the AOL room."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disturb','v.打扰；妨碍；使不安；弄乱；使恼怒','dɪsˈtɜːb','dɪsˈtɜːb','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Russian','adj.俄国的；俄语的n.俄语；俄国人','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smile','v.微笑n.微笑；笑容；喜色','ˈsmaɪ.əl','ˈsmaɪ.əl','noun','["He always puts a smile on my face.","the smile of the gods"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strict','adj.严格的；绝对的；精确的；详细的','stɹɪkt','stɹɪkt','adjective','["strict embrace","strict fiber","to keep strict watch"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('king','n.国王；最有势力者；王棋vi.统治；做国王vt.立…为王adj.主要的，最重要的，最大的','kɪŋ','kɪŋ','noun','["Henry VIII was the king of England from 1509 to 1547.","Howard Stern styled himself as the \"king of all media\".","In times of financial panic,cash is king."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('communication','n.通讯，[通信]通信；交流；信函','kəˌmjuːnɪˈkeɪʃən','kəˌmjuːnɪˈkeɪʃən','noun','["communication of a secret","Some say that communication is a necessary prerequisite for sentience; others say that it is a result thereof.","Surveillance was accomplished by means of intercepting the spies'' communications."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toothpaste','n.牙膏','ˈtuːθpeɪst','ˈtuːθpeɪst','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('his','pron.他的n.(His)人名；(法)伊斯','ˈhɪz','ˈhɪz','pronoun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('value','n.值；价值；价格；重要性；确切涵义v.评价；重视；估价','ˈvæljuː','ˈvæljuː','noun','["The Shakespearean Shylock is of dubious value in the modern world.","The value of my children''s happiness is second only to that of my wife.","He does not share his parents'' values."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('succeed','v.成功；继承；继任；兴旺','səkˈsiːd','səkˈsiːd','verb','["Autumn succeeds summer.","The persecution of any righteous practice has never succeeded in the face of history; in fact,it can expedite the collapse of the persecutory regime.","So,if the issue of the elder son succeed before the younger,I am king."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('restaurant','n.餐馆；[经]饭店','ˈɹɛs.t(ə).ɹ(ə)nt','ˈɹɛs.t(ə).ɹ(ə)nt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ability','n.能力，能耐；才能','əˈ.bɪl.ɪ.ti','əˈ.bɪl.ɪ.ti','noun','["This phone has the ability to have its software upgraded wirelessly.","She has an uncanny ability to defuse conflict."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoon','n.匙，勺子；一杓的量v.用匙舀；使成匙状','spuːn','spuːn','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('face','n.脸；表面；面子；面容；外观；威信v.向；朝','feɪs','feɪs','noun','["That girl has a pretty face.","Why the sad face?","Children! Stop making faces at each other!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shoe','n.鞋；蹄铁；外胎v.给……穿上鞋；穿……鞋','ʃuː','ʃuː','noun','["Get your shoes on now,or you''ll be late for school.","Throw the shoe from behind the line,and try to get it to land circling (a ringer) or touching the far stake.","Remember to turn the rotors when replacing the brake shoes,or they will wear out unevenly."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('big','adj.大的；重要的；量大的adv.大量地；顺利；夸大地n.(Big)人名；(土)比格','bɪɡ','bɪɡ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('produce','v.生产；引起；创作；生育，繁殖n.农产品，产品','pɹəˈdjuːs','pɹəˈdjuːs','verb','["to produce a side of a triangle","to produce a man''s life to threescore","highly produced sound"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('island','n.岛；岛屿；安全岛；岛状物adj.岛的vt.孤立；使成岛状','ˈaɪ̯lənd','ˈaɪ̯lənd','noun','["an island of colors on a butterfly''s wing","the island in the middle of a roundabout"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heavy','adj.沉重的；繁重的，巨大的；拥挤的；阴沉的n.重物；严肃角色adv.大量地；笨重地','ˈhe.vi','ˈhe.vi','noun','["With his wrinkled,uneven face,the actor always seemed to play the heavy in films.","A fight started outside the bar but the heavies came out and stopped it."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('electric','adj.电的；电动的；发电的；导电的；令人震惊的n.电；电气车辆；带电体','əˈlɛktɹɪk','əˈlɛktɹɪk','noun','["We had to sit in the dark because the electric was cut off."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('planet','n.行星','ˈplænət','ˈplænət','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weather','n.天气；气象；气候；处境v.经受住；使风化；侵蚀；使受风吹雨打adj.露天的；迎风的','ˈwɛðə','ˈwɛðə','noun','["Wooden garden furniture must be well oiled as it is continuously exposed to weather."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('guest','n.客人，宾客；顾客v.款待，招待adj.客人的；特邀的，客座的','ɡɛst','ɡɛst','noun','["The guests were let in by the butler.","Guests must vacate their rooms by 10 o''clock on their day of departure.","The guest for the broadcast was a leading footballer."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whom','pron.谁（who的宾格）','huːm','huːm','pronoun','["He''s a person with whom I work. (defining)","To whom it may concern,all business of John Smith Ltd. has now been transferred to Floggitt & Runne."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hard','adj.努力的；硬的；困难的；辛苦的；确实的；严厉的；猛烈的；冷酷无情的adv.努力地；困难地；辛苦地；接近地；猛烈地；牢固地n.(Hard)人名；(英、芬、瑞典)哈德','hɑːd','hɑːd','noun','["The prisoners were sentenced to three years'' hard."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clap','v.鼓掌，拍手；啪地关上n.鼓掌；拍手声','klæp','klæp','noun','["He summoned the waiter with a clap.","Off in the distance,he heard the clap of thunder.","His father''s affection never went further than a handshake or a clap on the shoulder."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fetch','v.取来；接来；到达；吸引n.取得；诡计','fɛtʃ','fɛtʃ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('each','adj.每；各自的adv.每个；各自pron.每个；各自','iːt͡ʃ','iːt͡ʃ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wish','n.希望；祝福；心愿v.祝愿；渴望；向…致问候语','wɪʃ','wɪʃ','noun','["My dearest wish is to see them happily married."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('environment','n.环境，外界','-mɪnt','-mɪnt','noun','["That program uses the Microsoft Windows environment."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shy','adj.害羞的；畏缩的，胆怯的v.投；畏缩；惊退；厌恶n.投掷；惊跳','ʃaɪ','ʃaɪ','noun','["coconut shy"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('murder','v.谋杀，凶杀n.谋杀，凶杀','ˈmɜːdə(ɹ)','ˈmɜːdə(ɹ)','noun','["The defendant was charged with murder.","There have been ten unsolved murders this year alone.","This headache is murder."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('afford','v.给予，提供；买得起n.(Afford)人名；(英)阿福德','əˈfɔːd','əˈfɔːd','verb','["I think we can afford the extra hour it will take.  We can only afford to buy a small car at the moment.","A affords his goods cheaper than B.","Grapes afford wine.  Olives afford oil.  The earth affords fruit.  The sea affords an abundant supply of fish."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('not','adv.表示否定，不n.“非”（计算机中逻辑运算的一种）','nɒt','nɒt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('must','aux.必须，一定；可以，应当；很可能n.绝对必要的事物；未发酵葡萄汁','','','noun','["If you''ll be out all day,a map is a must."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enemy','n.敌人，仇敌；敌军adj.敌人的，敌方的','ˈɛnəmi','ˈɛnəmi','noun','["Crush the enemy!","Rally together against a common enemy."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pride','n.自豪；骄傲；自尊心v.使得意，以…自豪','pɹaɪd','pɹaɪd','noun','["He had pride of ownership in his department.","to be in the pride of one''s life.","A pride of lions often consists of a dominant male,his harem and their offspring,but young adult males ''leave home'' to roam about as bachelors pride until able to seize/establish a family pride of their own."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smoke','n.烟；抽烟；无常的事物v.冒烟，吸烟；抽烟；弥漫','sməʊk','sməʊk','noun','["Can I bum a smoke off you?;  I need to go buy some smokes.","Hey,you got some smoke?","I''m going out for a smoke."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('act','v.扮演；装作，举动像n.行为，行动；法令，法案；（戏剧，歌剧的）一幕，段；装腔作势','æk','æk','noun','["an act of goodwill","He was caught in the act of stealing.","The pivotal moment in the play was in the first scene of the second act."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('underground','adv.在地下；秘密地adj.地下的；秘密的；先锋派的n.地下；地铁；地道；地下组织；秘密活动；先锋派团体','ˈʌndəɡɹaʊnd','ˈʌndəɡɹaʊnd','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('camp','v.露营；扎营n.露营','kʰɛəmp','kʰɛəmp','noun','["a hunter''s camp"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('total','adj.全部的；完全的；整个的v.总数达n.总数，合计','ˈtəʊ.təl','ˈtəʊ.təl','noun','["A total of £145 was raised by the bring-and-buy stall.","The total of 4,5 and 6 is 15."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jacket','n.羽绒滑雪衫；西装短外套；短上衣，夹克；土豆皮；书籍的护封；文件套，公文夹v.给…穿夹克；给…装护套；给…包上护封；〈口〉打','ˈd͡ʒæk.ɪt','ˈd͡ʒæk.ɪt','noun','["Cook the potatoes in their jackets."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('address','v.演说；从事；忙于；写姓名地址；向…致辞；与…说话；提出；处理n.地址；演讲；致辞；说话的技巧；称呼','æˈdɹɛs','æˈdɹɛs','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('north','n.北，北方adj.北方的；朝北的adv.在北方，向北方','noːθ','noːθ','noun','["Minnesota is in the north of the USA.","Stock prices are heading north."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('watch','v.观察；注视；看守；警戒n.手表；监视；守护；值班人','wɒt͡ʃ','wɒt͡ʃ','noun','["More people today carry a watch on their wrists than in their pockets.","The second watch of the night began at midnight.","The watch stopped the travelers at the city gates."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('book','n.书籍；卷；帐簿；名册；工作簿v.预订；登记','buːk','buːk','noun','["He was frustrated because he couldn''t find anything about dinosaurs in the book.","I have three copies of his first book.","Genesis is the first book of the Bible."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('used','adj.习惯的；二手的，使用过的v.用（use的过去式）；（usedto）过去常做','juːzd','juːzd','verb','["soldiers who are used to hardships and danger","I used to get things done.","to use an animal cruelly"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('news','n.新闻，消息；新闻报导','njuːz','njuːz','noun','["Is there any news about the storm?","Did you hear/read/see the latest news?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pond','vt.筑成池塘vi.筑成池塘n.池塘','pɒnd','pɒnd','noun','["I haven''t been back home across the pond in twenty years."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('friend','n.朋友；助手；赞助者','fɹɛnd','fɹɛnd','noun','["John and I have been friends ever since we were roommates at college.   Trust is important between friends.   I used to find it hard to make friends when I was shy.","The Automobile Association is every motorist''s friend.   The police is every law-abiding citizen''s friend.","a friend of a friend;  I added him as a friend on Facebook,but I hardly know him."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vehicle','n.[车辆]车辆；工具；交通工具；运载工具；传播媒介；媒介物','ˈvɪː(ə).kəl','ˈvɪː(ə).kəl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weight','n.重量，重力；负担；砝码；重要性v.加重量于，使变重','weɪt','weɪt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sausage','n.香肠；腊肠；装香肠的碎肉','ˈsɑsɪd͡ʒ','ˈsɑsɪd͡ʒ','noun','["my little sausage"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hall','n.过道，门厅，走廊；会堂；食堂；学生宿舍；大厅，前厅；娱乐中心，会所','hɔːl','hɔːl','noun','["The drinking fountain was out in the hall.","The hotel had three halls for conferences,and two were in use by the convention.","The duke lived in a great hall overlooking the sea."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('with','prep.用；随着；支持；和…在一起n.(With)人名；(德、芬、丹、瑞典)维特','','','adverb','["Do you want to come with?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flag','v.标记；衰退；枯萎n.标志；旗子','flæɡ','flæɡ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interesting','adj.有趣的；引起兴趣的，令人关注的','ˈɪnt(ə)ɹɛstɪŋ','ˈɪnt(ə)ɹɛstɪŋ','verb','["Action films don''t really interest me."]');
