INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('future','n.未来；前途；期货；将来时adj.将来的，未来的','ˈfjuːt͡ʃə','ˈfjuːt͡ʃə','noun','["There is no future in dwelling on the past."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clothes','n.衣服','kləʊ(ð)z','kləʊ(ð)z','noun','["He is a respected man of the cloth."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('regard','n.注意；尊重；问候；凝视v.注重，考虑；看待；尊敬；把…看作；与…有关','ɹɪˈɡɑːd','ɹɪˈɡɑːd','noun','["He is held in great regard in Whitehall."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('active','adj.积极的；活跃的；主动的；有效的；现役的n.主动语态；积极分子','ˈæk.tɪv','ˈæk.tɪv','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miss','n.女士，小姐，年轻未婚女子','mɪs','mɪs','noun','["I think I’ll give the meeting a miss."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('southern','adj.南的；南方的n.南方人','ˈsʌðɚn','ˈsʌðɚn','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tonight','adv.在今晚n.今晚','təˈnaɪt','təˈnaɪt','noun','["I have high hopes for tonight."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('join','v.参加；结合；连接n.结合；连接；接合点','ˈdʒɔɪn','ˈdʒɔɪn','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('however','adv.无论如何；不管怎样（接副词或形容词）；然而；可是conj.无论以何种方式;不管怎样','hɑʊˈɛvə','hɑʊˈɛvə','adverb','["He told me not to do it. I,however,did it anyway. / I did it anyway,however. / (sometimes proscribed:) However,I did it anyway.","However clear you think you''ve been,many questions will remain.","Let me know when you''ve had your interview,however it goes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('floor','n.地板，地面；楼层；基底；议员席v.铺地板；打倒，击倒；（被困难）难倒','flɔː','flɔː','noun','["The room has a wooden floor.","Many sunken ships rest on the ocean floor.","Wooden planks of the old bridge''s floor were nearly rotten."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quarter','n.四分之一；地区；季度；一刻钟；两角五分；节v.住宿；驻扎num.四分之一','ˈkoː.tɘ','ˈkoː.tɘ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cup','n.杯子；奖杯；酒杯v.使成杯状；为…拔火罐','kʌp','kʌp','noun','["Pour the tea into the cup.","I drank two cups of water but still felt thirsty.","The World Cup is awarded to the winner of a quadrennial football tournament."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('machine','n.机械，机器；机构；机械般工作的人v.用机器制造','məˈʃin','məˈʃin','noun','["I called you earlier,but all I got was the machine.","Game developers assume they''re pushing the limits of the machine.","Bruce Campbell was a \"demon-killing machine\" because he made quick work of killing demons."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rainy','adj.下雨的；多雨的n.(Rainy)人名；(英)雷尼','ˈɹeɪni','ˈɹeɪni','adjective','["Due to the rainy weather,we decided not to play in the park."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candle','n.蜡烛；烛光；烛形物v.对着光检查','ˈkændl̩','ˈkændl̩','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complete','adj.完整的；完全的；彻底的v.完成','kəmˈpliːt','kəmˈpliːt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chicken','n.鸡肉；小鸡；胆小鬼，懦夫adj.鸡肉的；胆怯的；幼小的','ˈt͡ʃɪkɪn','ˈt͡ʃɪkɪn','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carry','v.拿，扛；携带；支持；搬运n.运载；[计]进位；射程','ˈkæ.ɹi','ˈkæ.ɹi','noun','["Adjust your carry from time to time so that you don''t tire too quickly.","The carry on this trade is 25 basis points per annum."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sand','n.沙；沙地；沙洲；沙滩；沙子v.撒沙于；以沙掩盖；用砂纸等擦平或磨光某物；使撒沙似地布满；给…掺沙子','sænd','sænd','noun','["The Canadian tar sands are a promising source of oil."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tree','n.树；木料；树状物v.把赶上树','tɹiː','tɹiː','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meal','n.一餐，一顿饭；膳食vi.进餐','miːl','miːl','noun','["Breakfast is the morning meal,lunch is the noon meal,and dinner,or supper,is the evening meal."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lion','n.狮子；名人；勇猛的人；社交场合的名流','ˈlaɪən','ˈlaɪən','noun','["Tigers and lions share a common ancestor from a few million years ago."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('record','v.记录，记载；标明；将录音n.档案，履历；唱片；最高纪录adj.创纪录的','ˈɹɛkɔːd','ˈɹɛkɔːd','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fork','n.叉；餐叉；耙v.叉起；使成叉状','fɔːk','fɔːk','noun','["West Fork White River and East Fork White River join together to form the White River of Indiana.","LibreOffice is a fork of OpenOffice.","Are you qualified to drive a fork?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finish','v.完成；结束；用完n.结束；完美；回味（葡萄酒）','ˈfɪnɪʃ','ˈfɪnɪʃ','noun','["The car''s finish was so shiny and new."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('start','v.开始；启动n.开始；起点','stɑːt','stɑːt','noun','["The movie was entertaining from start to finish.","He woke with a start.","Captured pieces are returned to the start of the board."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('license','n.执照，许可证；特许v.许可；特许；发许可证给','ˈlaɪsəns','ˈlaɪsəns','noun','["In order to enter the building,I need to show my license."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pen','n.钢笔；作家；围栏v.写；关入栏中','pɛn','pɛn','noun','["There are two steers in the third pen.","They caught him with a stolen horse,and he wound up in the pen again.","Two righties are up in the pen."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('low','adj.低的，浅的；卑贱的；粗俗的；消沉的adv.低声地；谦卑地，低下地n.低；低价；低点；牛叫声v.牛叫','ləʊ','ləʊ','noun','["Economic growth has hit a new low.","Unemployment has reached a ten-year low.","He is in a low right now"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whose','pron.谁的（疑问代词）','huːz','huːz','pronoun','["Several people have lost their suitcases. Whose have you found?","This car is blocking the way,but Mr Smith,whose it is,will be here shortly."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classmate','n.同班同学','ˈklɑːs.meɪt','ˈklɑːs.meɪt','noun','["Danny and I have been classmates for five years,but I''ve never spoken to him outside of lessons."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zoo','n.动物园','zuː','zuː','noun','["The shopping center was a zoo the week before Christmas."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('post','n.岗位；邮件；标杆v.张贴；公布；邮递；布置','pəʊst','pəʊst','noun','["ram a post into the ground"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('team','n.队；组v.使合作','tiːm','tiːm','noun','["The IT manager leads a team of three software developers."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('same','adj.相同的；同一的；上述的（通常与the连用）；无变化的pron.同样的事物或人（通常与the连用）adv.同样地（通常与the连用）n.(Same)人名；(意)萨梅','seɪm','seɪm','adjective','["Are you the same person who phoned me yesterday?","It took all night to find our hotel room,as we forgot our room number and each door looked the same.","You have the same hair I do!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('could','aux.能够v.能（can的过去式）','kʊd','kʊd','verb','["She can speak English,French,and German.   I can play football.   Can you remember your fifth birthday?","You can go outside and play when you''re finished with your homework.   Can I use your pen?","Animals can experience emotions."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secretary','n.秘书；书记；部长；大臣','ˈsɛk.ɹə.tɹi','ˈsɛk.ɹə.tɹi','noun','["Ban Ki-Moon was a secretary general of the United Nations."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('place','n.地方；住所；座位v.放置；任命；寄予','pleɪs','pleɪs','noun','["I''m in a strange place at the moment.","three decimal places;  the hundreds place","That''s what I said in the first place!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supermarket','n.超级市场；自助售货商店','ˌsuːpəˈmɑːkɪt','ˌsuːpəˈmɑːkɪt','noun','["I went to the supermarket to buy some food."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noise','n.[环境]噪音；响声；杂音v.谣传','nɔɪz','nɔɪz','noun','["He knew that it was trash day,when the garbage collectors made all the noise.","The problems with the new computer system are causing a lot of noise at Head Office."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stairs','n.楼梯；梯级（stair的复数）','ˈstɛəz','ˈstɛəz','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('northern','adj.北部的；北方的n.北部方言','ˈnɔːðn̩','ˈnɔːðn̩','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('field','n.领域；牧场；旷野；战场；运动场v.担任场外队员adj.扫描场；田赛的；野生的','fiːld','fiːld','noun','["There are several species of wild flowers growing in this field.","A crop circle was made in a corn field."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classroom','n.教室','ˈklɑːsɹʊm','ˈklɑːsɹʊm','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grade','n.年级；等级；成绩；级别；阶段v.评分；把…分等级','ɡɹeɪd','ɡɹeɪd','noun','["I gave him a good grade for effort.","He got a good grade on the test.","The grade of this hill is more than 5 percent."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cook','v.烹调，煮n.厨师，厨子','kuːk','kuːk','noun','["I''m a terrible cook,so I eat a lot of frozen dinners.","Police found two meth cooks working in the illicit lab."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('him','pron.他（宾格）n.(Him)人名；(东南亚国家华语)欣；(柬)亨；(中)谦(广东话·威妥玛)','əm','əm','pronoun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('move','n.移动；步骤；迁居；策略v.移动；搬家，迁移；离开','muːv','muːv','noun','["A slight move of the tiller,and the boat will go off course.","He made another move towards becoming a naturalized citizen.","She always gets spontaneous applause for that one move."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wash','n.洗涤；洗的衣服；化妆水；冲积物v.洗涤；洗刷；冲走；拍打','wɑʃ','wɑʃ','noun','["I''m going to have a quick wash before coming to bed.","hand wash","There''s a lot in that wash: maybe you should split it into two piles."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunny','adj.阳光充足的，和煦的；快活的；性情开朗的','ˈsʌni','ˈsʌni','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rose','n.玫瑰；粉红色；蔷薇（花）；粉红色的葡萄酒adj.玫瑰花的；玫瑰色的；粉红色的；带有玫瑰香味的vt.使成玫瑰色，使（面颊）发红；使有玫瑰香味vi.起义(rise的过去式)；升起；（数量）增加；休会','ɹəʊz','ɹəʊz','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seventh','n.第七；七分之一adj.第七的；七分之一的adv.居第七位地','ˈsɛv.ənθ','ˈsɛv.ənθ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ground','n.地面；土地；范围；战场;根据v.使接触地面；打基础；使搁浅adj.土地的；地面上的；磨碎的；磨过的','ɡɹaʊnd','ɡɹaʊnd','noun','["Look,I found a ten dollar bill on the ground!","The fox escaped from the hounds by going to ground.","He could not come on grounds of health,or on health grounds."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hundred','n.一百；许多adj.一百的；许多的num.百；百个','ˈhʌndɚd','ˈhʌndɚd','noun','["He made a hundred in the historic match."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leader','n.领导者；首领；指挥者','ˈlidɚ','ˈlidɚ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('story','n.故事；小说；新闻报道；来历；假话vt.用历史故事画装饰vi.说谎','ˈstɔː.ɹi','ˈstɔː.ɹi','noun','["The book tells the story of two roommates.","You’ve been telling stories again,haven’t you?","What will she do without being able to watch her stories?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nose','n.鼻子；嗅觉；突出的部分；探问v.嗅；用鼻子触','nəʊz','nəʊz','noun','["She has a cold in the nose.","the nose of a tea-kettle,a bellows,or a fighter plane","Red Rum only won by a nose."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('church','n.教堂；礼拜；教派adj.教会的；礼拜的v.领…到教堂接受宗教仪式','t͡ʃɜːt͡ʃ','t͡ʃɜːt͡ʃ','noun','["There is a lovely little church in the valley.","These worshippers make up the Church of Christ.","The Church of England separated from the Roman Catholic Church in 1534."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('also','adv.也；而且；同样conj.并且；另外n.(Also)人名；(罗)阿尔索','ˈɔːl.səʊ','ˈɔːl.səʊ','adverb','["They had porridge for breakfast,and also toast."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fill','v.装满，使充满；满足；堵塞；任职n.满足；填满的量；装填物','fɪl','fɪl','verb','["the bucket filled with rain;  the sails fill with wind","My heart filled with joy.","The pharmacist filled my prescription for penicillin."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sofa','n.沙发；长椅','ˈsəʊfə','ˈsəʊfə','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ninth','num.第九adj.第九的；九分之一的n.九分之一','naɪnθ','naɪnθ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bus','n.公共汽车','bɐs','bɐs','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inch','n.英寸；身高；少许v.使缓慢地移动','ɪntʃ','ɪntʃ','noun','["\"Don''t move an inch!\""]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hot','adj.热的；辣的；热情的；激动的；紧迫的adv.热；紧迫地v.变热n.(Hot)人名；(塞)霍特；(法)奥特','hɒt','hɒt','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('play','v.游戏；扮演；演奏；播放；同…比赛n.游戏；比赛；剧本','pleɪ','pleɪ','noun','["Children learn through play.","This kind of play helps the young lion cubs develop their hunting skills.","After the rain break,play resumed at 3 o''clock."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postman','n.邮递员；邮差','ˈpəʊsmən','ˈpəʊsmən','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('touch','v.接触；触动；使轻度受害n.接触；触觉；格调；少许','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('white','adj.白色的；白种的；纯洁的n.白色；洁白；白种人','waɪt','waɪt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breakfast','n.早餐；早饭v.吃早餐','ˈbɹɛkfəst','ˈbɹɛkfəst','noun','["You should put more protein in her breakfast so she will grow.","We serve breakfast all day."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('object','n.目标；物体；客体；宾语v.提出…作为反对的理由','ˈɒb.d͡ʒɛkt','ˈɒb.d͡ʒɛkt','noun','["Mary Jane had been the object of Peter''s affection for years."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silk','n.丝绸；蚕丝；丝织物adj.丝的；丝绸的；丝制的vi.（玉米）处于长须的阶段中','sɪlk','sɪlk','noun','["The thread made of silk was barely visible."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('should','aux.应该；就；可能；将要','ʃʊd','ʃʊd','verb','["I hope that we shall win the game.","(determination): You shall go to the ball!","Let us examine that,shall we?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cheap','adj.便宜的；小气的；不值钱的adv.便宜地','t͡ʃiːp','t͡ʃiːp','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('public','adj.公众的；政府的；公用的；公立的n.公众；社会；公共场所','ˈpʌblɪk','ˈpʌblɪk','noun','["Members of the public may not proceed beyond this point."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beside','prep.在旁边；与…相比；和…无关','bɪˈsaɪd','bɪˈsaɪd','adverb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('main','n.主要部分，要点；体力；总管道adj.主要的，最重要的；全力的','meɪn','meɪn','verb','["He mains the same character as me in that game."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('angry','adj.生气的；愤怒的；狂暴的；（伤口等）发炎的','ˈæŋ.ɡɹi','ˈæŋ.ɡɹi','adjective','["An angry mob started looting the warehouse.","The broken glass left two angry cuts across my arm.","Angry clouds raced across the sky."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('method','n.方法；条理；类函数adj.使用体验派表演方法的','ˈmɛθəd','ˈmɛθəd','noun','["If one method doesn''t work,you should ask a friend to help you."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accident','n.事故；意外；[法]意外事件；机遇','ˈæk.sə.dənt','ˈæk.sə.dənt','noun','["to die by an accident","My insurance went up after the second accident in three months.","Beauty is an accident."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('night','n.夜晚，晚上；黑暗，黑夜adj.夜晚的，夜间的','naɪt','naɪt','noun','["How do you sleep at night when you attack your kids like that!?","a night on the town","I stayed my friend''s house for three nights."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('over','adv.结束；越过；从头到尾prep.越过；在…之上；遍于…之上adj.结束的；上面的vt.越过n.(Over)人名；(俄、西、土)奥韦尔','ˈəʊ.və(ɹ)','ˈəʊ.və(ɹ)','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('football','n.足球，橄榄球vi.踢足球；打橄榄球','fʷʊʔt̚bɑɫ','fʷʊʔt̚bɑɫ','noun','["Roman and medieval football matches were more violent than any modern type of football.","Each team scored three goals when they played football.","Each team scored two touchdowns when they played football."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yet','adv.还；但是；已经conj.但是；然而n.(Yet)人名；(东南亚国家华语)一','jɛt','jɛt','adverb','["He has never yet been late for an appointment;   I’m not yet wise enough to answer that;   Have you finished yet?","The workers went to the factory early and are striking yet.","The riddle will be solved yet."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snake','n.蛇；阴险的人v.迂回前进','ˈsneɪk','ˈsneɪk','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fresh','adj.新鲜的；清新的；淡水的；无经验的n.开始；新生；泛滥adv.刚刚，才；最新地','fɹɛʃ','fɹɛʃ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imagine','v.想像；猜想；臆断','ɪˈmædʒ.ɪn','ɪˈmædʒ.ɪn','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everyday','adj.每天的，日常的n.平时；寻常日子','ˈɛvɹiˌdeɪ','ˈɛvɹiˌdeɪ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('either','adj.两者之中任一的；两者之中每一的prep.任何一个conj.也（用于否定句或否定词组后）；根本pron.任一，两方，随便哪一个；两者中的一个或另一个','ˈaɪð.ə(ɹ)','ˈaɪð.ə(ɹ)','adverb','["I don''t like him,and I don''t like her either."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('past','n.过去；往事adj.过去的；结束的prep.越过；晚于adv.过；经过','pɑːst','pɑːst','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subject','n.主题；科目；[语]主语；国民adj.服从的；易患…的；受制于…的v.使…隶属；使屈从于…','ˈsʌb.dʒɪkt','ˈsʌb.dʒɪkt','adjective','["He''s subject to sneezing fits.","The local board sets local policy,subject to approval from the State Board."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Miss','n.女士，小姐，年轻未婚女子','mɪs','mɪs','noun','["I think I’ll give the meeting a miss."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('personal','adj.个人的；身体的；亲自的n.人事消息栏；人称代名词','ˈpɜː.sən.əl','ˈpɜː.sən.əl','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('knee','n.膝盖，膝v.用膝盖碰','niː','niː','noun','["Penny was wearing a miniskirt,so she skinned her exposed knees when she fell.","To make a knee.","the knee of a graph"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('note','n.笔记；音符；票据；注解；纸币；便笺；照会；调子v.注意；记录；注解','nəʊt','nəʊt','noun','["a poet of note"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ourselves','pron.我们自己；我们亲自','aʊəˈsɛlvz','aʊəˈsɛlvz','pronoun','["We should keep this for ourselves.","We did it ourselves."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('building','n.建筑；建筑物v.建筑；建立；增加（build的ing形式）','ˈbɪl.dɪŋ','ˈbɪl.dɪŋ','noun','["The building of the bridge will be completed in a couple of weeks.","My sister lives in that apartment building."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('memory','n.记忆，记忆力；内存，[计]存储器；回忆','ˈmɛm(ə)ɹi','ˈmɛm(ə)ɹi','noun','["Memory is a facility common to all animals.","I have no memory of that event.","This data passes from the CPU to the memory."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('introduction','n.介绍；引进；采用；入门；传入','ˌɪntɹəˈdʌkʃən','ˌɪntɹəˈdʌkʃən','noun','["the introduction of a new product into the market"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dentist','n.牙科医生','ˈdɛntɪst','ˈdɛntɪst','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('loud','adj.大声的，高声的；不断的；喧吵的adv.大声地，高声地，响亮地n.(Loud)人名；(英)劳德','laʊd','laʊd','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unit','n.单位，单元；装置；[军]部队；部件','ˈjuː.nɪt','ˈjuː.nɪt','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('return','v.返回；报答n.返回；归还；回球adj.报答的；回程的；返回的','ɹɪˈtɜːn','ɹɪˈtɜːn','noun','["I expect the house to be spotless upon my return.","Do you want a one-way or a return?","Last year there were 250 returns of this product,an improvement on the 500 returns the year before."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('left','adj.左边的；左派的；剩下的adv.在左面n.左边；左派；激进分子v.离开（leave的过去式）','lɛft','lɛft','noun','["The political left is holding too much power."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('once','adv.一次；曾经conj.一旦n.一次，一回','wɒn(t)s','wɒn(t)s','adverb','["I have only once eaten pizza.","He was once the most handsome man around.","Once three is three."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dead','adj.无生命的；呆板的；废弃了的adv.完全地n.死者','diːd','diːd','noun','["Have respect for the dead."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('example','n.例子；榜样vt.作为…的例子；为…做出榜样vi.举例','əɡˈzæmpl̩','əɡˈzæmpl̩','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technology','n.技术；工艺；术语','tɛkˈnɒlədʒi','tɛkˈnɒlədʒi','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('butterfly','n.蝴蝶；蝶泳；举止轻浮的人；追求享乐的人','ˈbʌtə(ɹ)flaɪ','ˈbʌtə(ɹ)flaɪ','noun','["butterfly tape","I get terrible butterflies before an exam."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illness','n.病；疾病','ˈɪl.nəs','ˈɪl.nəs','noun','["Her grandmother had passed away after a long illness.","Many working days this year have been lost through illness."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('article','n.文章；物品；条款；[语]冠词v.订约将…收为学徒或见习生；使…受协议条款的约束','ˈɑːtɪkəl','ˈɑːtɪkəl','noun','["a sales article","The Articles of War are a set of regulations [...] to govern the conduct of [...] military [...] forces","Each of the chelicerae is composed of two articles,forming a powerful pincer."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swimming','n.游泳；目眩adj.游泳的；游泳用的；善于游泳的；晕眩的v.游泳；漂浮；旋转（swim的ing形式）','ˈswɪmɪŋ','ˈswɪmɪŋ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dance','n.舞蹈；舞会；舞曲v.跳舞；跳跃；飘扬adj.舞蹈的；用于跳舞的','dæːns','dæːns','noun','["So how much longer are we gonna do this dance?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tent','n.帐篷；住处；帷幕v.用帐篷遮盖；使在帐篷里住宿','tɛnt','tɛnt','noun','["We were camping in a three-man tent."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('my','pron.我的int.哎呀（表示惊奇等）；喔唷n.(My)人名；(越)美；(老、柬)米','mi','mi','interjection','["My,what big teeth you have!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lucky','adj.幸运的；侥幸的','ˈlʌki','ˈlʌki','adjective','["The downed pilot is very lucky to be alive.","a lucky cast"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('but','conj.但是；而是；然而adv.仅仅，只prep.除…以外n.(But)人名；(俄、罗)布特；(越)笔','bʊt','bʊt','noun','["It has to be done – no ifs or buts."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hour','n.小时；钟头；课时；…点钟','ˈaʊɚ','ˈaʊɚ','noun','["I spent an hour at lunch.","The hour grows late and I must go home.","This place is an hour away from where I live."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('noon','n.中午；正午；全盛期','nuːn','nuːn','noun','["1885,When night was at its noon I heard a voice chanting the Koran in sweetest accents — Sir Richard Burton,The Book of the Thousand Nights and One Night,Night 17:"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('funny','adj.有趣的，好笑的，滑稽的；（口）稀奇的，古怪的，奇异的；有病的，不舒服的；狡猾的，欺骗（性）的，可疑的，不光明n.滑稽人物；笑话，有趣的故事；滑稽连环漫画栏；（英）（比赛用）单人双桨小艇','ˈfʊnɪ','ˈfʊnɪ','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('movie','n.电影；电影院；电影业adj.电影的','ˈmuːvi','ˈmuːvi','noun','["Let''s go to the movies."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('newspaper','n.报纸','ˈnjuːsˌpeɪpə','ˈnjuːsˌpeɪpə','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('out','adv.出现；在外；出局；出声地；不流行地adj.外面的；出局的；下台的n.出局prep.向；离去v.出来；暴露','æɔt','æɔt','noun','["They wrote the law to give those organizations an out."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('against','prep.反对，违反；靠；倚；防备adj.不利的；对立的','/əˈɡeɪnst/','/əˈɡɛnst/','preposition','["It is hard work to swim against the current.","The rain pounds against the window.","The kennel was put against the back wall."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discovery','n.发现，发觉；被发现的事物','/dɪsˈkʌvəɹi/','/dɪsˈkʌvəɹi/','noun','["This latest discovery should eventually lead to much better treatments for disease.","Automatic discovery of RSS feeds by a Web browser.","The prosecution moved to suppress certain items turned up during discovery."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('student','n.学生；学者','/ˈstjuː.dənt/','/ˈstu.dn̩t/','noun','["He is a student of life."]');
