INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('instruction','n.指令，命令；指示；教导；用法说明','/ɪnˈstɹʌkʃən/','/ɪnˈstɹʌkʃən/','noun','["Instruction will be provided on how to handle difficult customers."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('supper','n.晚餐，晚饭；夜宵','/ˈsʌpə/','/ˈsʌpɚ/','noun','["a fish supper; a pizza supper"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fisherman','n.渔夫；渔人','/ˈfɪʃəmən/','/ˈfɪʃɚmən/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flower','n.花；精华；开花植物v.成熟，发育；开花；繁荣；旺盛','/ˈflaʊ.ə/','/ˈflaʊ.ɚ/','noun','["We transplanted the flowers to a larger pot.","The dogwoods are in flower this week.","We selected the flower of the applicants."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lot','n.份额；许多；命运；阄adv.（与形容词和副词连用）很，非常；（与动词连用）非常pron.大量，许多v.分组，把…划分（常与out连用）；把（土地）划分成块','/lɒt/','/lɑt/','noun','["lots of people think so","a lot of stationery","a bad lot"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('or','conj.或，或者；还是n.(Or)人名；(中)柯(广东话·威妥玛)；(柬)奥；(土、匈、土库、阿塞、瑞典)奥尔','/ɔː(ɹ)/','/ɚ/','conjunction','["He might get cancer,or be hit by a bus,or God knows what.","It‘’s raining! Come inside or you‘’ll catch a cold!","The country Myanmar,or Burma"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maybe','adv.也许；可能；大概n.可能性；不确定性','/ˈmeɪbi/','/ˈmeɪbi/','noun','["The results of the poll were inconclusive. We got two yeses,three nos,and four maybes.","About your raise: it‘’s a big maybe."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duty','n.责任；[税收]关税；职务','/ˈdjuːti/','/duːti/','noun','["We don‘’t have a duty to keep you here.","I’m on duty from 6 pm to 6 am."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('count','v.计算；认为n.计数；计算；伯爵','/kaʊnt/','/kaʊnt/','noun','["Give the chairs a quick count to check if we have enough.","He has a 3–2 count with the bases loaded.","Can you count to a hundred?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirty','n.三十年代num.三十adj.三十个的','/ˈθɜːti/','/ˈθɝti/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goal','n.目标；球门，得分数；终点vi.攻门，射门得分','/ɡɒʊl/','/ɡoʊl/','noun','["My lifelong goal is to get into a Hollywood movie."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dictionary','n.字典；词典','/ˈdɪkʃəˌnɛɹi/','/ˈdɪkʃəˌnɛɹi/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shirt','n.衬衫；汗衫，内衣','/ʃɜːt/','/ʃɝt/','noun','["It can take a while to learn how to iron a shirt properly."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meeting','n.会议；会见；集会；汇合点v.会面；会合（meet的ing形式）','/ˈmiːtɪŋ/','/ˈmitɪŋ/','noun','["Meeting him will be exciting. I enjoy meeting new people.","We need to have a meeting about that soon.","What has the meeting decided."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('half','n.一半；半场；半学年adv.一半地；部分地adj.一半的；不完全的；半途的','/hɑːf/','/hɑːf/','noun','["I ate the slightly smaller half of the apple.","Three-quarters minus a quarter is a half.","a half bushel; a half hour; a half dollar; a half view"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('short','adj.短的；不足的；矮的，低的n.短；缺乏；短路；短裤adv.不足；突然；唐突地','/ʃoːt/','/ʃɔɹt/','noun','["38 short suits fit me right off the rack.","Jones smashes a grounder between third and short.","The market decline was terrible,but the shorts were buying champagne."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tie','v.系；约束；打结；与…成平局n.领带；平局；鞋带；领结；不分胜负','/taɪ/','/taɪ/','noun','["It‘’s two outs in the bottom of the ninth,tie score.","the sacred ties of friendship or of duty","Ties work to maintain structural integrity in windstorms and earthquakes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hope','n.希望；期望；信心v.希望；期望','/həʊp/','/hoʊp/','verb','["I am still hoping that all will turn out well.","I hope you all the best."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eighty','n.八十；八十岁；八十年代adj.八十的，八十个的；八十岁的num.八十','[ˈ(ʔ)eɪ̯ɾi]','[ˈ(ʔ)eɪ̯ɾi]','numeral','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('private','adj.私人的；私有的；私下的n.列兵；二等兵','/ˈpɹaɪvət/','/ˈpɹaɪvət/','noun','["If you want to learn ballet,consider taking privates.","Her address is private; you can‘’t have it.","private property"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prize','n.奖品；奖赏；战利品v.珍视；捕获；估价adj.获奖的','/pɹaɪz/','/pɹaɪz/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wife','n.妻子，已婚妇女；夫人','/waɪf/','/waɪf/','noun','["A new wife for the gander is introduced into the pen."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twelfth','adj.第十二的，第十二个的；十二分之一的n.第十二；月的第十二日','/twɛlfθ/','/twɛlfθ/','noun','["A twelfth of 240 is 20.","She finished twelfth in the race."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shorts','n.短裤','/ʃɔː(ɹ)ts/','/ʃɔː(ɹ)ts/','noun','["38 short suits fit me right off the rack.","Jones smashes a grounder between third and short.","The market decline was terrible,but the shorts were buying champagne."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('write','v.写，写字；写作，作曲；写信','/ɹaɪt/','/ɹaɪt/','noun','["How many writes per second can this hard disk handle?","The pupil wrote his name on the paper.","My uncle writes newspaper articles for The Herald."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('energy','n.[物]能量；精力；活力；精神','/ˈɛnəd͡ʒi/','/ˈɛnɚd͡ʒi/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sir','n.先生；（用于姓名前）爵士；阁下；（中小学生对男教师的称呼）先生；老师','/ˈsə(ɹ)/','/ˈsɝ/','noun','["Excuse me,sir,do you know the way to the art museum?","Sir,yes,sir!\nDon‘’t you sir me,private! I work for a living!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('store','n.商店；储备，贮藏；仓库v.贮藏，储存','/stɔː/','/stɔɹ/','noun','["This building used to be a store for old tires.","I need to get some milk from the grocery store.","The main store of 1000 36-bit words seemed large at the time."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grass','n.草；草地，草坪v.放牧；使……长满草；使……吃草','[ɡɹ̠äːs]','[ɡɹ̠äːs]','noun','["What just happened must remain secret. Don‘’t be a ‘’grass."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soup','n.汤，羹；马力v.加速；增加马力','/suːp/','/sup/','noun','["Pho is a traditional Vietnamese soup."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('street','n.街道adj.街道的','/stɹiːt/','/ʃtɹiːt/','noun','["Walk down the street until you see a hotel on the right.","I live on the street down from Joyce Avenue.","I got some pot cheap on the street."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fact','n.事实；实际；真相','/fækt/','/fækt/','noun','["In this story,the Gettysburg Address is a fact,but the rest is fiction.","Gravity is a fact,not a theory.","Let‘’s look at the facts of the case before deciding."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('help','v.帮助；促进；治疗；补救n.帮助；补救办法；帮忙者；有益的东西','/hɛlp/','/hɛlp/','noun','["I need some help with my homework.","He was a great help to me when I was moving house.","I can‘’t find anything in the help about rotating an image."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('till','n.[地理][水文]冰碛；放钱的抽屉；备用现金prep.直到conj.直到为止v.耕种；犁','/tɪl/','/tɪl/','preposition','["I have to work till eight o‘’clock tonight.","They led him till his tent","Maybe you can,maybe you can‘’t: you won‘’t know till you try."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tale','n.故事；传说；叙述；流言蜚语','/ˈteɪl/','/ˈteɪl/','noun','["Don‘’t tell tales!","the Canterbury Tales"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alive','adj.活着的；活泼的；有生气的','/əˈlaɪv/','/əˈlaɪv/','adjective','["As long as the plant is alive,he will continue to water it.","to keep the affections alive","Although quite dull during the day,the main street comes alive at night,with many bars and clubs opening."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oil','n.油；石油；油画颜料v.加油；涂油；使融化','/ɔɪl/','/ɔɪl/','noun','["I prefer to paint in oil"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lovely','adj.可爱的；令人愉快的；爱恋的；秀丽的，优美的n.美女；可爱的东西','/ˈlʌvli/','/ˈlʌvli/','noun','["a calendar depicting young lovelies in bikinis","Goodbye,my lovely.","It‘’s a lovely day and the sun is shining."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('role','n.角色；任务','/ɹəʊl/','/ɹəʊl/','noun','["Her dream was to get a role in a Hollywood movie,no matter how small.","The role of women has changed significantly in the last century.","Local volunteers played an important role in cleaning the beach after the oil spill."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiet','adj.安静的；安定的；不动的；温顺的n.安静；和平v.使平息；安慰','/ˈkwaɪ.ət/','/ˈkwaɪ.ət/','noun','["There was a strange quiet in the normally very lively plaza.","When you quiet,we can start talking.","Can you quiet your child? He‘’s making lots of noise."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('test','n.试验；检验v.试验；测试','/test/','/test/','noun','["Climbing the mountain tested our stamina.","to test the soundness of a principle; to test the validity of an argument","He tested positive for cancer."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('include','v.包含，包括','/ɪnˈkluːd/','/ɪnˈkluːd/','noun','["I will purchase the vacation package if you will include car rental.","Does this volume of Shakespeare include his sonnets?","You have to include the strings library to use this function."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plain','adj.平的；简单的；朴素的；清晰的n.平原；无格式；朴实无华的东西adv.清楚地；平易地','/pleɪn/','/pleɪn/','adjective','["Throughout high school she worried that she had a rather plain face.","I plain forgot.","Tell me plain: do you love me or no?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somewhere','adv.在某处；到某处n.某个地方','/ˈsʌm.hweːɹ/','/ˈsʌm.wɛɹ/','noun','["I must have left my glasses somewhere.","He plans to go somewhere warm for his vacation."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spirit','n.精神；心灵；情绪；志气；烈酒v.鼓励；鼓舞；诱拐','/ˈspɪɹɪt/','/ˈspiɹɪt/','noun','["A wandering spirit haunts the island.","School spirit is at an all-time high.","In the spirit of forgiveness,we didn‘’t press charges."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('office','n.办公室；政府机关；官职；营业处','/ˈɑfɪs/','/ˈɔfɪs/','noun','["When the office of Secretary of State is vacant,its duties fall upon an official within the department.","She held office as secretary of state until she left office to run for office.","The office of the Secretary of State is cleaned when it is vacant."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('healthy','adj.健康的，健全的；有益于健康的','/ˈhɛl.θi/','/ˈhɛl.θi/','adjective','["He was father to three healthy kids.","A healthy diet and exercise can help to maintain proper weight.","Sam unwrapped the sandwich and took a healthy bite out of the middle."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twentieth','n.二十分之一adj.第二十的；二十分之一的num.第二十','/ˈtwɛni.əθ/','/ˈtwɛni.əθ/','noun','[]');
