INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('smart','adj.聪明的；巧妙的；敏捷的；厉害的；潇洒的；剧烈的；时髦的n.(Smart)人名；(法)斯马尔；(英、德)斯马特','/smɑːt/','/smɑɹt/','verb','["After being hit with a pitch,the batter exclaimed \"Ouch,my arm smarts!\""]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('panda','n.熊猫；猫熊','/ˈpændə/','/ˈpændə/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('train','n.火车；行列；长队；裙裾v.培养；训练；瞄准','/tɹeɪn/','/tɹeɪn/','noun','["She trained seven hours a day to prepare for the Olympics.","You can‘’t train a pig to write poetry.","I trained with weights all winter."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('park','n.公园；[交]停车场v.停放；放置；寄存','[paːk]','[paːk]','noun','["A country‘’s tank park or artillery park.","I parked the drive heads of my hard disk before travelling with my laptop.","Let‘’s park that until next week‘’s meeting."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('born','v.出世（bear的过去分词）adj.天生的n.(Born)人名；(柬)邦；(英、西、俄、捷、德、瑞典、匈)博恩','/ˈbɔːn/','/ˈbɔɹn/','verb','["Judging from the look on his face,he wasn‘’t bearing good news.","By my readings,we‘’re bearing due south,so we should turn about ten degrees east."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('progress','n.进步，发展；前进v.前进，进步；进行','/ˈpɹɒɡɹɛs/','/ˈpɹoʊɡɹɛs/','noun','["Testing for the new antidote is currently in progress.","Science has made extraordinary progress in the last fifty years.","The thick branches overhanging the path made progress difficult."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zebra','n.[脊椎]斑马adj.有斑纹的','/ˈziːbɹə/','/ˈziːbɹə/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nurse','v.看护，护理；照顾；培养；给…喂奶n.护士；奶妈，保姆','/nɜːs/','/nɝs/','noun','["They hired a nurse to care for their young boy.","The nurse made her rounds through the hospital ward.","Eton College has been called \"the chief nurse of England‘’s statesmen\"."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('promise','n.许诺，允诺；希望v.允诺，许诺；给人以…的指望或希望','/ˈpɹɒmɪs/','/ˈpɹɑmɪs/','noun','["if I make a promise,I always stick to it;  he broke his promise","She shows great promise as an actress.","He promised to never return to this town again."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('girl','n.女孩；姑娘，未婚女子；女职员，女演员；（男人的）女朋友','/ɡɵːl/','/ɡɝl/','noun','["Your girl turned up on our doorstep.","Don‘’t be such a girl!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('traffic','n.交通；运输；贸易；[通信]通信量v.用…作交换；在…通行','/ˈtɹæfɪk/','/ˈtɹæfɪk/','noun','["The traffic is slow during rush hour."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('translate','v.翻译；转化；解释；转变为；调动','/ˈtɹɛnzlæet/','/tɹæn(t)s-/','noun','["William was translated by the blow to the head he received,being unable to speak for the next few minutes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('risk','n.风险；危险；冒险v.冒…的危险','/ɹɪsk/','/ɹɪsk/','noun','["2006,Trever Ramsey on BBC News website,Exercise ‘’cuts skin cancer risk‘’ read at http//news.bbc.co.uk/1/hi/health/4764535.stm on 14 May 2006"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('top','n.顶部，顶端；上部；首席；陀螺v.高出，超越；结束；达到顶点adj.最高的，顶上的；头等的','/tɒp/','/tɑp/','noun','["His kite got caught at the top of the tree.","The boy was amazed at how long the top would spin.","I prefer being a top,and my boyfriend prefers being a bottom."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('candy','v.用糖煮；使结晶为砂糖；美化n.糖果（等于sweets）；冰糖（等于sugarcandy，rockcandy）；毒品adj.新潮的（服饰）；甜言蜜语的','/ˈkændi/','/ˈkændi/','noun','["Fruits preserved in sugar candy after a time."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('west','n.西；西方；西部adj.西方的；朝西的adv.在西方；向西方；自西方','/wɛst/','/wɛst/','noun','[]');
