INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('successful','adj.成功的；一帆风顺的','/səkˈsɛsfl̩/','/səkˈsɛsfl̩/','adjective','["a successful use of medicine;  a successful experiment;  a successful enterprise"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dinner','n.晚餐，晚宴；宴会；正餐','/ˈdɪnə/','/ˈdɪnəɹ/','noun','["Give the dog its dinner."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stranger','n.陌生人；外地人；局外人','/ˈstɹeɪndʒə/','/ˈstɹeɪndʒɚ/','adjective','["He thought it strange that his girlfriend wore shorts in the winter.","I moved to a strange town when I was ten.","That gentleman is a stranger to me.  Children are taught not to talk to strangers."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('education','n.教育；培养；教育学','/ˌɛdjʊˈkeɪʃn̩/','/ˌɛdjʊˈkeɪʃn̩/','noun','["2016-06-17 AROP JOSEPH \"Education is the slight hammer that breaks the yoke of ignorance,and moulds knowledge,skills,ideas,good moral values in a person be it a child,a youth or full grown adult. no matter a persons age learning never stops\".","He has had a classical education."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('war','n.战争，斗争；军事，战术；冲突，对抗，竞争v.打仗，作战；对抗','/wɔː/','/wɔɹ/','noun','["The war was largely between Sunni and Shia militants.","You look like you‘’ve been through the wars."]');
