INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('certain','adj.某一；必然的；确信；无疑的；有把握的pron.某些；某几个n.(Certain)人名；(葡)塞尔塔因；(法)塞尔坦','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necessary','adj.必要的；必需的；必然的n.必需品','/ˈnɛsəsɹɪ/','/ˈnɛsəˌsɛɹi/','noun','["Although I wished to think that all was false,it was yet necessary that I,who thus thought,must in some sense exist.","If it is absolutely necessary to use public computers,you should plan ahead and forward your e-mail to a temporary,disposable account."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bridge','n.桥；桥牌；桥接器；船桥v.架桥；渡过','/bɹɪd͡ʒ/','/bɹɪd͡ʒ/','noun','["With enough cable,we can bridge this gorge.","The two groups were able to bridge their differences."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('level','n.水平；标准；水平面adj.水平的；平坦的；同高的v.瞄准；拉平；变得平坦','/ˈlɛv.əl/','/ˈlɛv.əl/','noun','["Hand me the level so I can tell if this is correctly installed.","By the end of the day,we‘’d dug down to the level of the old basement floor.","The sound level is much too high; this hurts my ears.   We‘’ve reached a new level of success."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('son','n.儿子；孩子（对年轻人的称呼）；男性后裔','/sɒn/','/sɒn/','noun','["Before the birth of the man‘’s child,he said: \"I want a son,not a daughter.\"","He was a son of the mafia system.","The pharaohs were believed to be sons of the Sun."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('available','adj.可获得的；可购得的；可找到的；有空的','/əˈveɪləb(ə)l/','/əˈveɪləb(ə)l/','adjective','["We have an available candidate.","The list shows the available products in the store.","This is an available plea."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pie','n.馅饼；饼图；爱说话的人vt.使杂乱','/paɪ/','/paɪ/','noun','["The family had steak and kidney pie for dinner and cherry pie for dessert.","Shepherd‘’s pie is made of mince covered with mashed potato.","I‘’d like to see someone pie the chairman of the board."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('population','n.人口；[生物]种群，[生物]群体；全体居民','/ˌpɒpjʊˈleɪʃən/','/pɒpjuːˈleɪʃən/','noun','["The population of New Jersey will not stand for this!","India has the third-largest population of English-speakers in the world.","The town’s population is only 243."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('care','n.关怀；照料；谨慎；忧虑v.照顾；关心；喜爱；顾虑','/kɛə/','/ke(ə)ɹ/','noun','["Care should be taken when holding babies.","I don‘’t have a care in the world.","dental care"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ugly','adj.丑陋的；邪恶的；令人厌恶的','/ˈʌɡli/','/ˈʌɡli/','noun','["He played an ugly trick on us.","an ugly temper; to feel ugly","With all this competition,expect things to get ugly."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luck','n.运气；幸运；带来好运的东西v.靠运气，走运；凑巧碰上','/lʊk/','/lʌk/','noun','["Gilbert had some bad luck yesterday — he got pick-pocketed and lost fifty dollars.","He blew on the dice for luck.","He has a lot of luck with the ladies,perhaps it is because of his new motorbike."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('close','adj.紧密的；亲密的；亲近的v.关；结束；使靠近adv.紧密地n.结束','/kləʊz/','/kloʊz/','noun','["We owe them our thanks for bringing the project to a successful close."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('university','n.大学；综合性大学；大学校舍','/juːnɪˈvɜːsətiː/','/junɨˈvɝsəti/','noun','["The only reason why I haven‘’t gone to university is because I can‘’t afford it."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pretty','adj.漂亮的；可爱的；优美的adv.相当地；颇n.有吸引力的事物（尤指饰品）；漂亮的人','/ˈpɹɪti/','/ˈpɝti/','noun','["We‘’ll stop at the knife store and look at the sharp pretties."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('die','v.死亡；凋零；熄灭n.冲模，钢模；骰子','/daɪ/','/daɪ/','verb','["He died a hero‘’s death.","I‘’m dying for a packet of crisps.","The day our sister eloped,she died to our mother."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('round','n.圆；循环；一回合；圆形物adj.圆的；完全的；大概的；肥胖的adv.在周围；迂回地；朝反方向；挨个v.完成；围捕；绕行；弄圆prep.附近；绕过；大约；在…周围','/ˈɹaʊnd/','/ˈɹaʊnd/','adverb','["High above,vultures circled around.","Everybody please gather around.","An adult elephant weighs around five tons."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirsty','adj.口渴的，口干的；渴望的，热望的','/ˈθɜː(ɹ)st.i/','/ˈθɜː(ɹ)st.i/','adjective','["After all that work I am really thirsty.","After the president left office,the nation was thirsty for change.","This is the third time that girl brought up her crush. She must really be thirsty for her."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('free','adj.免费的；自由的，不受约束的；[化学]游离的v.使自由，解放；释放adv.自由地；免费n.(Free)人名；(英)弗里','/fɹiː/','/fɹiː/','noun','["He was given free rein to do whatever he wanted.","It‘’s free real estate.","We had a wholesome,filling meal,free of meat.  I would like to live free from care in the mountains."]');
