INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fast','adj.快速的，迅速的；紧的，稳固的adv.迅速地；紧紧地；彻底地v.禁食，斋戒n.斋戒；绝食','/fɑːst/','/fæst/','noun','["That rope is dangerously loose. Make it fast!","I am going to buy a fast car.","a fast billiard table"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('litter','n.垃圾；轿，担架；一窝（动物的幼崽）；凌乱v.乱丢；给…垫褥草；把…弄得乱七八糟','/ˈlɪtə(ɹ)/','/ˈlɪtɚ/','noun','["sleep in the litter","drop litter","the cat‘’s litter"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('water','n.水；海水；雨水；海域，大片的水v.使湿；供以水；给…浇水','/ˈwoːtə/','/ˈwɑtəɹ/','noun','["By the action of electricity,the water was resolved into its two parts,oxygen and hydrogen.","And God said,Let the waters under the heaven be gathered together unto one place,and let the dry land appear: and it was so.","The boat was found within the territorial waters."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('station','n.车站；驻地；地位；身份v.配置；安置；驻扎','/ˈsteɪʃən/','/ˈsteɪʃən/','noun','["She had ambitions beyond her station.","I used to listen to that radio station.","I was stationed on the pier."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strawberry','n.草莓；草莓色','/ˈstɹɔːb(ə)ɹi/','/ˈstɹɔˌbɛɹi/','noun','["They went to pick strawberries today.","She has the best strawberry patch I‘’ve ever seen.","I‘’d like a large strawberry shake."]');
