INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seem','v.似乎；像是；装作n.(Seem)人名；(英)西姆','/siːm/','/siːm/','verb','["He seems to be ill.   Her eyes seem blue.   It seems like it is going to rain later.   How did she seem to you?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('history','n.历史，历史学；历史记录；来历','/ˈhɪst(ə)ɹi/','/ˈhɪst(ə)ɹi/','noun','["History repeats itself if we don’t learn from its mistakes.","He teaches history at the university.   History will not look kindly on these tyrants.   He dreams of an invention that will make history.","What is your medical history?   The family‘’s history includes events best forgotten."]');
