INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beyond','prep.超过；越过；那一边；在较远的一边adv.在远处；在更远处n.远处','/biˈjɒnd/','/biˈjɑnd/','noun','["2017 July 13,Joseph Gamp \"Marvel release stirring new set images of Black Panther and we are BEYOND excited\" Metro (UK)","She had no reason for the conviction beyond the very inadequate one that she had seen him around London.","No swimming beyond this point."]');
