INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fit','v.安装；使……适应；使……合身；与……相符adj.健康的；合适的；恰当的；准备好的n.合身；发作；痉挛','/fɪt/','/fɪt/','noun','["Since he put on weight,his jeans have been a tight fit.","It‘’s hard to get a good fit using second-hand parts.","The Wonder Bread advertising research results showed the “White Picket Fence” commercial had strong fit ratings."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quite','adv.很；相当；完全','/kwaɪt/','/kwaɪt/','adverb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('high','adj.高的；高级的；崇高的；高音调的n.高水平；天空；由麻醉品引起的快感；高压地带adv.高；奢侈地','/haɪ/','/haɪ/','noun','["It was one of the highs of his career.","That pill gave me a high for a few hours,before I had a comedown.","A large high is centred on the Azores."]');
