INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heat','n.高温；压力；热度；热烈v.使激动；把…加热','/hit/','/hit/','noun','["This furnace puts out 5000 BTUs of heat.   That engine is really throwing off some heat.   Removal of heat from the liquid caused it to turn into a solid.","Stay out of the heat of the sun!","The chili sauce gave the dish heat."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fire','n.火；火灾；炮火；炉火；热情；激情；磨难v.点燃；解雇；开除；使发光；烧制；激动；放枪','/ˈfɑeə(ɹ)/','/ˈfaɪɚ/','noun','["We sat about the fire singing songs and telling tales.","During hot and dry summers many fires in forests are caused by regardlessly discarded cigarette butts.","The fire was laid and needed to be lit."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perhaps','adv.或许；（表示不确定）也许；（用于粗略的估计）或许；（表示勉强同意或其实不赞成）也许；可能n.假定；猜想；未定之事','/pəˈhæps/','/pɚˈhæps/','noun','["Perhaps John will come over for dinner."]');
