INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('besides','adv.此外；而且prep.除…之外','/biˈsaɪdz/','/biˈsaɪdz/','adverb','["I don‘’t feel like going out tonight. Besides,I have to work tomorrow morning anyway.","I have been to Spain but nowhere besides.","I don‘’t want to go anywhere besides India."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('all','adj.全部的adv.全然地；越发n.全部pron.全部','/ɔːl/','/ɑl/','noun','["She gave her all,and collapsed at the finish line.","The butter is all.","It suddenly went all quiet."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advice','n.建议；忠告；劝告；通知','/ədˈvaɪs/','/ædˈvaɪs/','noun','["She was offered various piece of advice on what to do with her new-found wealth.","late advices from France","An advice of an incoming settlement payment order may be given to an off-line receiving bank."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('music','n.音乐，乐曲','/ˈmjuːzɪk/','/ˈmjuzɪk/','noun','["I keep listening to this music because it‘’s a masterpiece."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practice','n.实践；练习；惯例v.练习；实习；实行','/ˈpɹæktɪs/','/ˈpɹæktɪs/','noun','["He will need lots of practice with the lines before he performs them.","Being on a team is hard: you‘’re always having to go to practice while everyone else is taking it easy.","She ran a thriving medical practice."]');
