INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('listen','v.听，倾听；听从，听信n.听，倾听','/ˈlɪs.ən/','/ˈlɪs.ən/','noun','["Give the motor a listen and tell me if it sounds off.","Please listen carefully as I explain.  I like to listen to music.","You should listen for the starting gun."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trade','n.贸易，交易；行业；职业v.交易，买卖；以物易物','/tɹeɪd/','/tɹeɪd/','noun','["I did no trades with them once the rumors started.","The skilled trades were the first to organize modern labor unions.","It is not a retail showroom. It is only for the trade."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('may','aux.可以，能够；可能，也许；祝，愿；会，能','/meɪ/','/meɪ/','verb','["you may smoke outside;  may I sit there?","he may be lying;  Schrödinger‘’s cat may or may not be in the box","may you win;  may the weather be sunny"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('everything','pron.每件事物；最重要的东西；（有关的）一切；万事','/ˈɛvɹiθɪŋ/','/ˈɛvɹiθɪŋ/','pronoun','["I checked the list again and everything is done.","A:What do you want to do at the amusement park?\nB:Everything!","She wasn‘’t feeling well this morning but now everything is fine."]');
