INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bye','int.再见n.轮空；次要的东西adj.次要的','/baɪ/','/baɪ/','noun','["Craig‘’s Crew plays the bye next week."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('physics','n.物理学；物理现象','/ˈfɪz.ɪks/','/ˈfɪz.ɪks/','noun','["Newtonian physics was extended by Einstein to explain the effects of travelling near the speed of light; quantum physics extends it to account for the behaviour of atoms.","The physics of car crashes would not let Tom Cruise walk away like that."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('between','prep.在…之间adv.在中间','/bɪˈtwiːn/','/bəˈtwin/','noun','["I want to buy one that costs somewhere between forty and fifty dollars.","conversation between friends","Between you and me,I think the boss is crazy.  Let‘’s keep this between ourselves."]');
