INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juice','n.（水果）汁，液；果汁','/d͡ʒuːs/','/d͡ʒus/','noun','["Squeeze the orange and some juice will come out.","I’d like two orange juices please."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('animal','n.动物','/ˈænɪməl/','/ˈænɪməl/','noun','["A cat is an animal,not a plant. Humans are also animals,under the scientific definition,as we are not plants.","My students are animals.","He‘’s a political animal."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('member','n.成员；会员；议员','/ˈmɛmbə/','/ˈmɛmbɚ/','noun','["The I-beams were to become structural members of a pedestrian bridge.","The zip file holding the source code of this application has 245 members."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tape','n.胶带；磁带；带子；卷尺v.录音；用带子捆扎；用胶布把…封住','/teɪ̯p/','/teɪ̯p/','noun','["Hand me some tape. I need to fix a tear in this paper.","After the party there was tape all over the place.","Jones broke the tape in 47.77 seconds,a new world record."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shame','n.羞耻，羞愧；憾事，带来耻辱的人v.使丢脸，使羞愧','/ʃeɪm/','/ʃeɪm/','noun','["The teenager couldn’t bear the shame of introducing his parents.","It was a shame not to see the show after driving all that way.","Shame,you poor thing,you must be cold!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('black','adj.黑色的；黑人的；邪恶的n.黑色；黑人；黑颜料v.使变黑；把鞋油等涂在…上；把（眼眶）打成青肿','/blak/','/blak/','noun','["At this point black makes a disastrous move.","black drinking fountain; black hospital","I was dealt two red queens,and he got one of the black queens."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heaven','n.天堂；天空；极乐','/hɛvn/','/hɛvn/','noun','[]');
