INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('easy','adj.容易的；舒适的adv.不费力地，从容地vi.停止划桨vt.发出停划命令','/ˈiːzi/','/ˈizi/','noun','["Now that I know it‘’s taken care of,I can rest easy at night.","It‘’s often easy to wake up but hard to get up.","Rich people live in easy circumstances."]');
