INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('the','art.这；那adv.更加（用于比较级，最高级前）','/ði/','/ði/','adverb','["It looks weaker and weaker,the more I think about it.","I‘’m much the wiser for having had a difficult time like that."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('love','n.恋爱；亲爱的；酷爱；喜爱的事物；爱情，爱意；疼爱；热爱；爱人，所爱之物v.爱，热爱；爱戴；赞美，称赞；喜爱；喜好；喜欢；爱慕','/lʊv/','/lʌv/','noun','["Hello love,how can I help you?","I love my spouse.   I love you!","Mold loves moist,dark places."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brush','n.刷子；画笔；毛笔；争吵；与某人有效冲突；灌木丛地带；矮树丛；狐狸尾巴v.刷；画；','/bɹʌʃ/','/bɹʌʃ/','noun','["She gave her hair a quick brush.","He has had brushes with communism from time to time.","donwloading brushes for Photoshop"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('truck','n.卡车；交易；手推车v.驾驶卡车；以物易物adj.（美）运货汽车的','/tɹʌk/','/tɹʌk/','noun','["Mexican open-bed trucks haul most of the fresh produce that comes into the United States from Mexico.","Last week,Cletus trucked 100 pounds of lumber up to Dubuque.","Keep on trucking!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mouth','n.口，嘴；河口v.做作地说，装腔作势地说；喃喃地说出','/mʌʊθ/','/maʊθ/','noun','["\"Open your mouth and say ‘’aah‘’,\" directed the doctor.","The mouth of the river is a good place to go birdwatching in spring and autumn.","The mouth of a cave"]');
