INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('term','n.术语；学期；期限；条款；(代数式等的)项v.把…叫做','/tɜːm/','/tɝm/','noun','["\"Alright,look...we can spend the holidays with your parents,but this time it will be on my terms.\"","The term of a lease agreement is the period of time during which the lease is effective,and may be fixed,periodic,or of indefinite duration.","Be sure to read the terms and conditions before signing."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yellow','adj.黄色的；黄皮肤的n.黄色；黄种人；黄色颜料v.使变黄或发黄','/jɛlə/','/ˈjɛl.oʊ/','noun','["2012 March 2,Andrew Grice,\"Yellow rebels take on Clegg over NHS ‘’betrayal‘’\",The Independent","the black-yellow coalition"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mirror','n.镜子；真实的写照；榜样v.反射；反映','/ˈmɘ.ɹɘ/','/ˈmiɹ.ɚ/','noun','["I had a look in the mirror to see if the blood had come off my face.","His story is a mirror into the life of orphans growing up.","Although the content had been deleted from his blog,it was still found on some mirrors."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condition','n.条件；情况；环境；身份v.决定；使适应；使健康；以…为条件','/kənˈdɪʃən/','/kənˈdɪʃən/','noun','["Environmental protection is a condition for sustainability.   What other planets might have the right conditions for life?   The union had a dispute over sick time and other conditions of employment.","My aunt couldn‘’t walk up the stairs in her condition.","National reports on the condition of public education are dismal.   The condition of man can be classified as civilized or uncivilized."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('position','n.位置，方位；职位，工作；姿态；站位v.安置；把……放在适当位置','/pəˈzɪʃ(ə)n/','/pəˈzɪʃ(ə)n/','noun','["Chief of Staff is the second-highest position in the army.","My position on this issue is unchanged.","Stand in this position,with your arms at your side."]');
