INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cap','n.盖；帽子v.脱帽致意','/kæp/','/kæp/','noun','["The children were all wearing caps to protect them from the sun.","He took the cap off the bottle and splashed himself with some cologne.","He had golden caps on his teeth."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('law','n.法律；规律；法治；法学；诉讼；司法界vi.起诉；控告vt.控告；对…起诉','/lɔː/','/lɔ/','noun','["entrapment is against the law","A new law forbids driving on that road.","It was a territory without law,marked by violence."]');
