INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cold','adj.寒冷的；冷淡的，不热情的；失去知觉的n.寒冷；感冒adv.完全地','/kɔʊld/','/koʊld/','adjective','["A cold wind whistled through the trees.","The forecast is that it will be very cold today.","She was so cold she was shivering."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thread','n.线；螺纹；思路；衣服；线状物；玻璃纤维；路线v.穿过；穿线于；使交织','[θɾ̪̊ɛd]','[θɾ̪̊ɛd]','noun','["All of these essays have a common thread.","thread a needle","I think I can thread my way through here,but it’s going to be tight."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('iron','n.熨斗；烙铁；坚强v.熨；用铁铸成adj.铁的；残酷的；刚强的','/ˈaɪən/','/ˈaɪɚn/','noun','["wrought iron,ductile iron,cast iron,pig iron,gray iron","He appeared easygoing,but inside he was pure iron.","He lifts iron on the weekends."]');
