INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('background','n.背景；隐蔽的位置v.作…的背景adj.背景的；发布背景材料的','/ˈbæk.ɡɹaʊnd/','/ˈbæk.ɡɹaʊnd/','noun','["The lawyer had a background in computer science.","The photographer let us pick a background for the portrait.","The antivirus program is running in the background."]');
