INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('name','n.名称，名字；姓名；名誉v.命名，任命；指定；称呼；提名；叫出adj.姓名的；据以取名的','/neɪm/','/neɪm/','noun','["I‘’ve never liked the name my parents gave me so I changed it at the age of twenty.","Stop calling me names!","Halt in the name of the law!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('add','v.加；增加；加起来；做加法n.加法，加法运算','/æd/','/æd/','noun','["When the player has fought the boss for one minute,two adds will arrive from the back and must be dealt with.","to add numbers","to add a column of numbers"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('year','n.年；年度；历年；年纪；一年的期间；某年级的学生','/jɪə/','/jɜː/','noun','["we moved to this town a year ago;  I quit smoking exactly one year ago","Mars goes around the sun once in a Martian year,or 1.88 Earth years.","A normal year has 365 full days,but there are 366 days in a leap year."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prison','n.监狱；监禁；拘留所vt.监禁，关押','/ˈpɹɪzən/','/ˈpɹɪzən/','noun','["The cold stone walls of the prison had stood for over a century.","Prison was a harrowing experience for him.","The academy was a prison for many of its students because of its strict teachers."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sentence','n.[语][计]句子，命题；宣判，判决v.判决，宣判','[ˈsɛntn̩t͡s]','[ˈsɛntn̩t͡s]','noun','["The court returned a sentence of guilt in the first charge,but innocence in the second.","The judge declared a sentence of death by hanging for the infamous cattle rustler.","The children were made to construct sentences consisting of nouns and verbs from the list on the chalkboard."]');
