INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nor','conj.也不；也不是adv.也不；也没有n.(Nor)人名；(中)挪(广东话·威妥玛)；(马来、俄)诺尔；(柬)诺','/nɔː/','/nɔːɹ/','conjunction','["Nor did I stop to think,but ran.","I am neither hungry nor thirsty nor tired.","The struggle didn‘’t end,nor was it any less diminished."]');
