INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wound','n.创伤，伤口v.使受伤','/wuːnd/','/wund/','noun','["It took a long time to get over the wound of that insult.","The police officer wounded the suspect during the fight that ensued.","The actor‘’s pride was wounded when the leading role went to his rival."]');
