INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warn','v.警告，提醒；通知n.(Warn)人名；(英)沃恩；(德)瓦恩','/wɔːn/','/wɔɹn/','verb','["Don‘’t let me catch you running in the corridor again,I warn you.","A sign warns trespassers off/away from the site."]');
