INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('master','v.控制；精通；征服n.硕士；主人；大师；教师adj.主人的；主要的；熟练的','/ˈmastə/','/ˈmæstɚ/','noun','["Mark Twain was a master of fiction.","She has a master in psychology.","He is a master of marine biology."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salt','n.盐；风趣，刺激性adj.咸水的；含盐的，咸味的；盐腌的；猥亵的v.用盐腌；给…加盐；将盐撒在道路上使冰或雪融化','/sɔlt/','/sɑlt/','noun','["Attic salt","to salt fish,beef,or pork; to salt the city streets in the winter","The brine begins to salt."]');
