INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('large','adj.大的；多数的；广博的adv.大大地；夸大地n.大','/ˈlɑːd͡ʒ/','/ˈlɑɹd͡ʒ/','noun','["Getting a car tricked out like that will cost you 50 large.","One small coffee and two larges,please.","Russia is a large country.   The fruit-fly has large eyes for its body size.   He has a large collection of stamps."]');
