INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nobody','pron.没有人，无人n.无足轻重的人','/ˈnəʊ.bɒ.di/','/ˈnoʊ.bɑ.di/','noun','["Whether you‘’re a nobody or a player,everyone in Tinseltown wants to be King of Hollywood! - Conquering Hollywood","I asked several people,but nobody knew how."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empty','adj.空的；空闲的；空虚的v.空，倒出','/ˈɛmpti/','/ˈɛmpti/','noun','["Put the empties out to be recycled.","The cinema emptied quickly after the end of the film.","Salmon River empties on the W shore about 2 miles below Bear River."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wish','v.希望，想要；但愿；祝，祝愿；盼望，企求','/wɪʃ/','/wɪʃ/','noun','["My dearest wish is to see them happily married.","I‘’ll come tomorrow,if you wish it.","We wish you a Merry Christmas."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tie','v.[tying]拴，扎，捆；把…打结，系上；连接，使有关联；不分胜负','/taɪ/','/taɪ/','noun','["It‘’s two outs in the bottom of the ninth,tie score.","the sacred ties of friendship or of duty","Ties work to maintain structural integrity in windstorms and earthquakes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wise','adj.有智慧的，聪明的；英明的，明智的；博学的，贤明的','/waɪz/','/waɪz/','verb','["After Mo had a word with him,he wised up.","\"It is a profitable thing,if one is wise,to seem foolish\" - Aeschylus","Don‘’t get wise with me!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('serious','adj.严重的，危急的；重要的，重大的；认真的，严肃的，庄重的','/ˈsɪə.ɹi.əs/','/ˈsɪəɹ.i.əs/','adjective','["It was a surprise to see the captain,who had always seemed so serious,laugh so heartily.","This is a serious problem. We‘’ll need our best experts.","After all these years,we‘’re finally getting serious attention."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laugh','v.笑n.笑，笑声','/laːf/','/læf/','noun','["His deep laughs boomed through the room.","Your new hat‘’s an absolute laugh,dude.","There were many laughing children running on the school grounds."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conversation','n.交谈，谈话','/ˌkɒn.vəˈseɪ.ʃən/','/ˌkɑn.vəɹˈseɪ.ʃən/','noun','["I had an interesting conversation with Nicolas yesterday about how much he‘’s getting paid."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('area','n.面积；地区，地方；领域，范围','/ˈɛə̯ɹɪə̯/','/ˈæɹ.i.ə/','noun','["The photo is a little dark in that area.","The plans are a bit vague in that area."]');
