INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enter','v.进入；参加，加入','/ˈɛntə(ɹ)/','/ˈɛntɚ/','noun','["You should knock before you enter,unless you want to see me naked.","to enter a knife into a piece of wood;  to enter a boy at college,a horse for a race,etc.","My twelve-year-old son will be entering his teens next year.  She had planned to enter the legal profession."]');
