INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallery','n.画廊，美术馆；楼座；廊台，走廊','/ˈɡæləɹi/','/ˈɡæləɹi/','noun','["a clip-art gallery in a wordprocessor"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lesson','n.课；教学单元；一堂课，一节课；教训，经验','/ˈlɛsn̩/','/ˈlɛsn̩/','noun','["In our school a typical working week consists of around twenty lessons and ten hours of related laboratory work.","Nature has many lessons to teach to us.","I hope this accident taught you a lesson!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('destroy','v.破坏，毁灭','/dɪˈstɹɔɪ/','/dɪˈstɹɔɪ/','verb','["Hooligans destroy unprovoked.","Smoking destroys the natural subtlety of the palate.","Destroying a rabid dog is required by law."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moon','n.月球，月亮；卫星','/muːn/','/muːn/','proper noun','["That''s no moon,you idiot... it''s a space station!","They stayed with their aunt and uncle for many moons.","The moons surrounding the city walls were built in the sixteenth century."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creative','adj.创造性的，具有创造力的','/kɹiˈeɪtɪv/','/kɹiˈeɪtɪv/','noun','["He is a visionary creative.","I''ve included in my portfolio all the creative I''ve completed in my five year design career.","a creative dramatist who avoids cliche"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('provide','v.供应，提供','/pɹəˈvaɪd/','/pɹəˈvaɪd/','verb','["It is difficult to provide for my family working on minimum wage.","Provide against disaster.","I''ll lend you the money,provided that you pay it back by Monday."]');
