INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lot','n.许多，大量；签，抽签；一块地，场地','/lɒt/','/lɑt/','noun','["lots of people think so","a lot of stationery","a bad lot"]');
