INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('low','adj.低的，矮的；低下的，低等的；粗劣的，低俗的；不充分的，缺乏的；意气','/ləʊ/','/loʊ/','noun','["Economic growth has hit a new low.","Unemployment has reached a ten-year low.","He is in a low right now"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('theme','n.主题，题目；【音】主旋律','/θiːm/','/θiːm/','noun','["We themed the birthday party around superheroes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wealth','n.财富，财产；丰富，大量','/wɛlθ/','/wɛlθ/','noun','["She brings a wealth of knowledge to the project."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wallet','n.皮夹子','/ˈwɒlɪt/','/ˈwɑlət/','noun','["The thief stole all the money and credit cards out of the old man''s wallet.","It''s unknown if the pro running back''s recent sex scandal will hit him in the wallet or not.","I won an auction online for a cheap CD wallet."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('doll','n.玩偶，玩具娃娃','/dɒl/','/dɑl/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chair','v.担任主席n.椅子；主席，主席席位','/t͡ʃɛə(ɹ)/','/t͡ʃɛəɹ/','noun','["All I need to weather a snowstorm is hot coffee,a warm fire,a good book and a comfortable chair.","My violin teacher used to play first chair with the Boston Pops.","Bob will chair tomorrow''s meeting."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centre','v.集中于n.圆心，正中；中心','/ˈsen.tə(ɹ)/','/ˈsɛn.tɚ/','noun','["shopping center,convention center,civic center,garment center,Lincoln Center for the Performing Arts,Rockefeller Center","the center of attention","He centered the heading of the document."]');
