INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tell','v.[told-told]讲，告诉；吩咐，命令；说明，显示；分辨，区分','/tɛl/','/tɛl/','noun','["All told,there were over a dozen.  Can you tell time on a clock?  He had untold wealth.","I want to tell a story;  I want to tell you a story.","Finally,someone told him the truth.  He seems to like to tell lies."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stomach','v.承受，忍受；吃得下n.胃，胃口；肚子，腹部','/ˈstʌmək/','/ˈstʌmək/','noun','["a good stomach for roast beef","I have no stomach for a fight today.","I can''t stomach her cooking."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('husband','n.丈夫','/ˈhʌz.bənd/','/ˈhʌz.bənd/','noun','["You should start dating so you can find a suitable husband.","While reading her book,Sally leaned back against her husband,wishing it were the human kind.","For my means,I''ll husband them so well,/ They shall go far. — Shakespeare."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appointment','n.约会；约定；任命，委派；职务，职位','/əˈpɔɪnt.mɛnt/','/əˈpɔɪnt.mɛnt/','noun','["His appointment was deemed suitable","the appointment of treasurer","I''m leaving work early because I have a doctor''s appointment."]');
