INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worldwide','adv.在世界各地，在全世界adj.世界范围的，全世界的','/ˈwɜːldwaɪd/','/ˈwɝldˌwaɪd/','adjective','["A large meteorite impact would cause worldwide extinction of life.","English is spoken worldwide."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bear','v.忍受，忍耐，经受住n.熊','/bɛə(ɹ)/','/bɑɹ/','noun','["That window can be a bear to open.","to bear a railroad stock","The great bear market starting in 1929 scared a whole generation of investors."]');
