INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consider','v.考虑，细想；认为，把…看作；关心，照顾','/kənˈsɪdə/','/kənˈsɪdɚ/','verb','["Consider that we’ve had three major events and the year has hardly begun.","I’m considering going to the beach tomorrow.","Consider yourself lucky,but consider your opponent skillful."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('day','n.天，一昼夜；白昼，白天；时期，时代；工作日；','/deɪ/','/deɪ/','noun','["I''ve been here for two days and a bit.","The day begins at midnight.","A day on Mars is slightly over 24 hours."]');
