INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('square','adj.正方形的；平方的；直角的v.求平方；求…的面n.正方形；平方；广场','/skwɛə(ɹ)/','/skwɛɚ/','noun','["64 is the square of 8.","Why do you always wear a tie? Don''t be such a square!","Enter your account number followed by a square."]');
