INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('park','v.停放n.公园；停车场','[paːk]','[paːk]','noun','["A country''s tank park or artillery park.","I parked the drive heads of my hard disk before travelling with my laptop.","Let''s park that until next week''s meeting."]');
