INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clear','adv.清晰地，清楚地adj.清楚的，明白的；无疑的，确信的；晴朗的；清澈的','/klɪə(ɹ)/','/klɪɹ/','noun','["a room ten feet square in the clear","If you clear the table,I''ll wash up.","Please clear all this stuff off the table."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clean','adj.清洁的，干净的；爱清洁的；清白的，公正的；','/kleːn/','/klin/','noun','["This place needs a clean.","Can you clean the windows today?","Clean your room right now!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meal','n.膳食，一餐，一顿；进餐','/miːl/','/miːl/','noun','["Breakfast is the morning meal,lunch is the noon meal,and dinner,or supper,is the evening meal."]');
