INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('third','num.第三n.三分之一','/θɜːd/','/tɜjd/','noun','["Jones came in third.","He ate a third of the pie. Divided by two-thirds.","Now put it into third."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('build','v.建筑，建造，盖；造n.体格；体形，身材','/bɪld/','/bɪld/','noun','["Rugby players are of sturdy build.","The computer company has introduced a new prototype build to beta testers.","I made a build that looked like the Parthenon in that game."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mean','v.[meant-meant]表示…的意思；意欲，打算；意指，意味着','/miːn/','/miːn/','verb','["Does she really mean what she said to him last night?","One faltering step means certain death.","Formality and titles mean nothing in their circle."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meat','n.肉','/miːt/','/mit/','noun','["A large portion of domestic meat production comes from animals raised on factory farms.","The butchery''s profit rate on various meats varies greatly.","The apple looked fine on the outside,but the meat was not very firm."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chew','v.咀嚼；咬住，不停地啃','/tʃuː/','/tʃu/','noun','["I popped the gum into my mouth and gave it a chew.","Phillip purchased a bag of licorice chews at the drugstore.","The school had banned chew and smokes from the school grounds,even for adults."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurry','v.使加快，催促；急运，急派；匆忙，赶紧n.急忙，匆忙，仓促','/ˈhʌ.ɹi/','/ˈhʌ.ɹi/','noun','["Why are you in such a big hurry?","There is no hurry on that paperwork.","He''s hurrying because he''s late."]');
