INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('railway','n.铁道，铁路','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strict','adj.严格的，严厉的；严谨的，精确的；完全的，','/stɹɪkt/','/stɹɪkt/','adjective','["strict embrace","strict fiber","to keep strict watch"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modest','adj.谦虚的，谨慎的；适度的','/ˈmɑdəst/','/ˈmɑdəst/','adjective','["He earns a modest amount of money.","modest thoughts or language"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('you','pron.你，你们','/jʉː/','/jə/','verb','["Both of you should get ready now.","You are all supposed to do as I tell you."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jump','n&v.跳跃，跳过；猛涨，激增','/dʒʌmp/','/dʒʌmp/','noun','["The boy took a skip and a jump down the lane.","He went off a jump.","There were a couple of jumps from the bridge."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('happen','v.发生；碰巧，恰好','/ˈhæpən/','/ˈhæpən/','verb','["Let me tell you how it happened.","Do you happen to have an umbrella?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sofa','n.沙发','/ˈsəʊfə/','/ˈsoʊfə/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pass','v.经过，穿过；传递，传送；度过；通过；批准','[pʰäːs]','[pʰäːs]','verb','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('past','adj.以前的，过去的；结束了的，不复存在的prep.晚于，在…之后n.昔日，','/pɑːst/','/pæst/','verb','["a book about a time machine that can transport people back into the past","past glories","during the past year"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('festival','n.节，节日，喜庆日','/ˈfɛstəvəl/','/ˈfɛstəvəl/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mile','n.英里','/maɪ̯l/','/maɪ̯l/','noun','["The shot missed by a mile.","The runners competed in the mile.","five miles over the speed limit"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shock','n.震动，冲击；震惊，惊愕；电震，电击，触电','/ʃɒk/','/ʃɑk/','noun','["The train hit the buffers with a great shock.","The disaster shocked the world."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('milk','v.挤n.牛奶','/mɪlk/','/mɪlk/','noun','["Table three ordered three milks. (Formally: The guests at table three ordered three glasses of milk.)","I take my tea with two milk(s) and two sugar."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('opportunity','n.机会，良机','/ˌɒp.əˈtjuː.nɪ.tɪ/','/ˌɑpɚˈtunəti/','noun','["The world is full of opportunities and it''s up to me to see them and pursue them.","Having a holiday is a great opportunity to relax.","The Court questioned the opportunity of introducing these measures in such an uncertain economic climate."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bill','n.账单；议案，法案；纸币，钞票；单子，节目单；招贴，海报','/bɪl/','/bɪl/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pancake','n.薄煎饼，烙饼','/ˈpæn.keɪk/','/ˈpæn.keɪk/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('active','adj.活跃的；积极的；主动的；起作用的','/ˈæk.tɪv/','/ˈæk.tɪv/','noun','["certain active principles","an active child or animal","active hostilities"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('court','v.献殷勤；追求，求爱；招致，导致n.法庭，法院；宫廷，朝廷；球场','/kɔːt/','/kɔɹt/','noun','["The girls were playing in the court.","The local sports club has six tennis courts and two squash courts.","He was courting big new accounts that previous salesman had not attempted."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('easy','adj.容易的，不费力的；舒适的，安逸的；随和的，友善的','/ˈiːzi/','/ˈizi/','noun','["Now that I know it''s taken care of,I can rest easy at night.","It''s often easy to wake up but hard to get up.","Rich people live in easy circumstances."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whose','pron.谁的；那个的，那些的','/huːz/','/huːz/','pronoun','["Several people have lost their suitcases. Whose have you found?","This car is blocking the way,but Mr Smith,whose it is,will be here shortly."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('population','n.人口；某领域的生物；族群；人口','/ˌpɒpjʊˈleɪʃən/','/pɒpjuːˈleɪʃən/','noun','["The population of New Jersey will not stand for this!","India has the third-largest population of English-speakers in the world.","The town’s population is only 243."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('route','n.路线，路程','/ɹʉːt/','/ɹaʊt/','noun','["The route was used so much that it formed a rut.","Here is a map of our delivery routes.","Follow Route 49 out of town."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('Monday','n.星期一','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adult','adj.发育成熟的；成熟的，成人的n.成年人；成年动物','/əˈdʌlt/','/əˈdʌlt/','noun','["an adult human,animal,or plant","adult clothes","This program contains adult content. Parental discretion is advised."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relative','adj.相对的；比较的；有关的，相关的n.亲属，亲戚','[ˈɹɛl.ə.tʰɪv]','[ˈɹɛl.ə.tʰɪv]','noun','["Why do my relatives always talk about sex?","The relative URL /images/pic.jpg,when evaluated in the context of http://example.com/docs/pic.html,corresponds to the absolute URL http://example.com/images/pic.jpg.","relative to your earlier point about taxes,..."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attitude','n.态度；看法，意见','/ˈætɪˌtjuːd/','/ˈætɪtud/','noun','["The ballet dancer walked with a graceful attitude.","Don''t give me your negative attitude.","The airliner had to land with a nose-up attitude after the incident."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('treatment','n.治疗，疗法；对待，待遇；处理','/ˈtɹiːtmənt/','/ˈtɹiːtmənt/','noun','["He still has nightmares resulting from the treatment he received from his captors.","A treatment or cure is applied after a medical problem has already started."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mirror','v.反映；反射，映照n.镜子','/ˈmɘ.ɹɘ/','/ˈmiɹ.ɚ/','noun','["I had a look in the mirror to see if the blood had come off my face.","His story is a mirror into the life of orphans growing up.","Although the content had been deleted from his blog,it was still found on some mirrors."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compare','n&v.比较；比喻','/kəmˈpɛə/','/kəmˈpɛɚ/','noun','["Compare the tiger''s coloration with that of the zebra.","Astronomers have compared comets to dirty snowballs.","We compare \"good\" as \"good\",\"better\",\"best\"."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bottle','n.瓶子','/ˈbɑ.təl/','/ˈbɑ.təl/','noun','["Beer is often sold in bottles.","I only drank a bottle of beer.","The baby wants a bottle."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hot','adj.热的；辣的；激烈的，热烈的；急躁的，易发怒的；最新的，热','/hɒt/','/hɑt/','verb','["He forgot that the frying pan was hot and burned his hand.","It is hotter in summer than in winter.","Aren''t you hot with that thick coat on?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('how','adv.怎么，怎样；多么，多少','/hæŏ/','/haʊ/','noun','["I am not interested in the why,but in the how.","How often do you practice?","How do you solve this puzzle?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('October','n.十月','','','','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hotel','n.旅馆，宾馆','/(h)əʊˈtɛl/','/hoʊˈtɛl/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('term','n.措词，术语；期限，任期；学期；','/tɜːm/','/tɝm/','noun','["\"Alright,look...we can spend the holidays with your parents,but this time it will be on my terms.\"","The term of a lease agreement is the period of time during which the lease is effective,and may be fixed,periodic,or of indefinite duration.","Be sure to read the terms and conditions before signing."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spare','adj.备用的；多余的；空闲的v.留出，抽出；饶恕，不伤害；使免遭，','/ˈspɛə(ɹ)/','/ˈspɛəɹ/','noun','["a spare diet","I have no spare time.","a spare anchor; a spare bed or room"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mine','pron.我的v.开矿，采矿n.矿，矿山；地雷；水雷','/maɪn/','/maɪn/','pronoun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mind','n.头脑，精神，理智；智力；注意力，心思；意向，想法','/maɪnd/','/maɪnd/','noun','["Despite advancing age,his mind was still as sharp as ever.","There was no doubt in his mind that they would win.","My mind just went blank."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chip','v.削下n.碎片；芯片','/tʃɪp/','/tʃɪp/','noun','["This cup has a chip in it.","Do you want sauce or mayonnaise on your chips?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('business','n.交易，生意；营业；商业；工作，任务；事务','/ˈbɪd.nəs/','/ˈbɪd.nəs/','noun','["I was left my father''s business.","He is in the motor and insurance businesses.","He''s such a poor cook,I can''t believe he''s still in business!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tail','v.附于其后；尾随，跟踪n.尾巴，尾状物；后部，尾部；踪迹','/teɪl/','/teɪl/','noun','["Most primates have a tail and fangs.","I''m gonna get me some tail tonight.","Tail that car!"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('staff','v.为…配备人员，任职于n.全体职工，工作人员；杠，棒；参谋部','/ˈstæf/','/stɑːf/','noun','["The company employed 10 new members of staff this month.","a constable''s staff"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possible','adj.可能的，做得到的；可接受的，合理的','/ˈpɒsɪbl̩/','/ˈpɑsəbl̩/','noun','["Jones is a possible for the new opening in sales.","It''s not just possible,it''s probable.","It''s possible for anyone to learn to pay the bagpipes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('right','adj.正确的；正当的，公正的；右边的；合适的；健康的，正常的；直的','/ˈɹaɪt/','/ˈɹaɪt/','adjective','["a right line","The kitchen counter formed a right angle with the back wall.","a right triangle,a right prism,a right cone"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('march','v.行军，前进；游行示威n.行进，行军；游行示威；进行，进展；[M-]三月','/mɑːtʃ/','/mɑɹtʃ/','noun','["the march of time"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meet','v.[met-met]遇见，碰到；接；和…见面，和…会面','/miːt/','/mit/','noun','["OK,let''s arrange a meet with Tyler and ask him.","This proposal meets my requirements. The company agrees to meet the cost of any repairs.","The eye met a horrid sight. He met his fate."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('answer','v.回答，答复；解答，解决；作n.回答，答复；答案，解决办法','/ˈan.sə/','/ˈæn.sɚ/','noun','["Her answer to his proposal was a slap in the face.","There is no simple answer to corruption."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stage','n.舞台，后台；平台，高台；楼层，楼架','/steɪd͡ʒ/','/steɪd͡ʒ/','noun','["Completion of an identifiable stage of maintenance such as removing an aircraft engine for repair or storage.","The band returned to the stage to play an encore.","The stage pulled into town carrying the payroll for the mill and three ladies."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('borrow','v.借，借入；借用，采用','/ˈbɔɹoʊ/','/ˈbɑɹoʊ/','noun','["This putt has a big left-to right borrow on it.","to borrow the style,manner,or opinions of another","Can I borrow a sheet of paper?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('junk','v.丢弃，废弃n.废旧物品，破烂','/dʒʌŋk/','/dʒʌŋk/','noun','["junk fish; junk trees","(On Facebook,a record collector wrote:) \"The newest addition to my Annette Hanshaw collection,I junked this beautiful flawless E-copy within walking distance from my house.\""]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('waiter','n.侍者，服务员','/ˈweɪtə/','/ˈweɪtɚ/','noun','["Waiter! There''s a fly in my soup."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('under','prep.在…下面，在…底下；少于；低于；在…管辖下，在…影响下','/ˈʊndə/','/ˈʌndɚ/','adjective','["Ensure the patient is sufficiently under.","It took the hypnotist several minutes to make his subject go under.","He served in World War II under General Omar Bradley."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('purse','n.钱包；女用小包','/pɜːs/','/pɝs/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spotlight','v.用聚光灯照；特别关注；突出报道n.聚光灯；公众的注意','','','noun','["Some people enjoy the spotlight.","We spotlight the star,but the supporting cast has all the great lines in this scene.","The news series served to spotlight corruption."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('represent','v.作为…的代表；描述；表示；象征；描绘，表现；阐明，说明；扮演','/ɹɛp.ɹɪ.ˈzɛnt/','/ɹɛp.ɹɪ.ˈzɛnt/','verb','["The sculptor represented a horse in bronze.","It has always been his dream to represent Hamlet on Broadway.","An attorney''s job is to represent his client in court"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quarter','n.四分之一；季，季度；一刻钟；25分的硬币；','/ˈkoː.tɘ/','/ˈk(w)ɔɹ.tɚ/','noun','["Quarter the horses in the third stable.","a quarter hour; a quarter century; a quarter note; a quarter pound","A quarter day is one terminating a quarter of the year."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('die','v.[dying]死，死亡；消失；停止运行；渴望；消','/daɪ/','/daɪ/','verb','["He died a hero''s death.","I''m dying for a packet of crisps.","The day our sister eloped,she died to our mother."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dig','v.挖（土等），掘（洞）n.挖苦，嘲讽','/dɪɡ/','/dɪɡ/','noun','["He guffawed and gave me a dig in the ribs after telling his latest joke.","a £1 charity shop dig","If the plane can''t pull out of the dive it is in,it''ll dig a hole in the ground."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sometimes','adv.不时；有时，间或','/ˈsʌmtaɪmz/','/ˈsʌmtaɪmz/','adjective','["Sometimes I sit and think,but mostly I just sit."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('promise','v.允诺，答应；有…可能，有希望n.承诺，诺言；可能性，希望','/ˈpɹɒmɪs/','/ˈpɹɑmɪs/','noun','["if I make a promise,I always stick to it;  he broke his promise","She shows great promise as an actress.","He promised to never return to this town again."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('down','adv.向下，在下面；处于低等地位，处于潦倒状况adj.沮丧prep.沿着…而下','/daʊn/','/daʊn/','noun','["I love almost everything about my job. The only down is that I can''t take Saturdays off.","I bet after the third down,the kicker will replace the quarterback on the field.","I haven''t solved 12 or 13 across,but I''ve got most of the downs."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hold','v.[held-held]拿，握；使保持某种状态；','/həʊld/','/hoʊld/','noun','["Keep a firm hold on the handlebars.","Can I have a hold of the baby?","Senator X placed a hold on the bill,then went to the library and placed a hold on a book."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tale','n.故事，传说','/ˈteɪl/','/ˈteɪl/','noun','["Don''t tell tales!","the Canterbury Tales"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('later','adv.后来；过一会儿adj.后来的，以后的，后面的；新近的；晚年的','/ˈleɪtə/','/ˈleɪtɚ/','adjective','["It was late in the evening when we finally arrived.","It was getting late and I was tired.","Late Latin is less fully inflected than classical Latin."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passport','n.护照','/ˈpɑːspɔːt/','/ˈpæspɔɹt/','noun','["You will have to bring your passport to prove who you are.","The tenor''s voice was his passport to the international concert circuit."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lookout','n.警戒，监视；■望台，监视哨；■望员，监视者；与个人有关的事情，任务','/ˈlʊkaʊt/','/ˈlʊkaʊt/','noun','["We kept a lookout all night,but nobody came.","The raid failed when the lookout noticed the enemy group.","Every man''s interest is his own lookout."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bird','n.鸟；禽','/bɜd/','/bɝd/','noun','["Ducks and sparrows are birds.","Mike went out with his bird last night."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('club','n.俱乐部，社团','/klʌb/','/klʌb/','noun','["She was sitting in a jazz club,sipping wine and listening to a bass player''s solo.","Michael stood you up?  Welcome to the club.","He clubbed the poor dog."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talk','v.说，讲话；交谈，谈论','/toːk/','/tɔk/','verb','["Although I don''t speak Chinese I managed to talk with the villagers using signs and gestures.","That''s enough about work,let''s talk holidays!","We talk French sometimes."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tall','adj.高的，身材高的；难以置信的；难以办成的','/tɔːl/','/tɑl/','noun','["Being tall is an advantage in basketball."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reply','n&v.回答，答复，以…作答','/ɹɪˈplaɪ/','/ɹɪˈplaɪ/','noun','["Joanne replied to Pete''s insult with a slap to his face."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('train','v.训练；培养n.列车，火车；一连串，一系列；行列','/tɹeɪn/','/tɹeɪn/','noun','["She trained seven hours a day to prepare for the Olympics.","You can''t train a pig to write poetry.","I trained with weights all winter."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('possibly','adv.大概，也许','/ˈpɒsɪbli/','/ˈpɑsəbli/','adverb','["It was possibly the costliest mistake in the organization''s history.","I couldn''t possibly be there on time."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('test','n&v.试验，测试；检验','/test/','/test/','noun','["Climbing the mountain tested our stamina.","to test the soundness of a principle; to test the validity of an argument","He tested positive for cancer."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('planet','n.行星','/ˈplænət/','/ˈplænɪt/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('count','v.点…的数目，计算；把…算入；认为，看作；值得考虑，有重要意义','/kaʊnt/','/kaʊnt/','noun','["Give the chairs a quick count to check if we have enough.","He has a 3–2 count with the bases loaded.","Can you count to a hundred?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brown','adj.棕色的，褐色的n.棕色，褐色','/bɹaʊn/','/bɹaʊn/','noun','["The browns and greens in this painting give it a nice woodsy feel.","Fry the onions until they brown.","Brown the onions in a large frying pan."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('take','v.[took-taken]带，携带；需要，花费；拿，取得；接受；吃，喝，服(药','/teɪk/','/teɪk/','noun','["What''s your take on this issue,Fred?","a new take on a traditional dish","Act seven,scene three,take two."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('misleading','adj.令人误解的，导致错误结论的；引入歧途的；欺骗的；迷惑人的','','','verb','["The preacher elaborated Satan''s ways to mislead us into sin"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('final','adj.最后的，最终的；决定性的，确定性的n.期末考试；决赛','/ˈfaɪ.nəl/','/ˈfaɪ.nəl/','noun','["final solution;   the final day of a school term","a final judgment;   the battle of Waterloo brought the contest to a final issue"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('some','adv.大约；稍微pron.一些，若干adj.一些，若干，有些；某个，某一','/sɐm/','/sʌm/','adverb','["I guess he must have weighed some 90 kilos.","Some enjoy spicy food,others prefer it milder.","Can I have some of them?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blank','adj.空白的，空着的；茫然的，无表情的','/blæŋk/','/blæŋk/','noun','["the double blank","I blanked out my previous entry.","She blanked me for no reason."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rather','adv.相当；有点儿；宁愿，宁可；更确切地说','/ˈɹɑːðə/','/ˈɹæðɚ/','verb','["I''d like this one rather than the other one.","It wasn''t supposed to be popular; rather,it was supposed to get the job done.","I didn''t want to leave. Or rather I did,just not alone."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('importance','n.重要','/ɪmˈpɔːtəns/','/ɪmˈpɔɹtəns/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('back','adv.回原处，回原状；向后，后仰着；还；以前；回，往回n.背，背部；后面，','/bæk/','/bæk/','noun','["Could you please scratch my back?","He sat in the back of the room.","The small boat raced over the backs of the waves."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miss','v.未击中，未达到；未赶上，错过；思念，想念；未明白；避免，逃脱n.小姐','/mɪs/','/mɪs/','noun','["I think I’ll give the meeting a miss.","I missed the target.","to miss an opportunity"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pound','v.强烈打击，猛击；心怦怦跳；费力地移动n.磅；英镑','/paʊnd/','/paʊnd/','noun','["the Rhode Island pound; the New Hampshire pound"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('company','n.公司，商号；陪伴，交往；同伴，朋友；客人；群，伙','/ˈkʌmp(ə)ni/','/ˈkʌmpəni/','noun','["Keep the house clean; I have company coming.","I treasure your company."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('just','adv.正好，恰恰正是；只是，仅仅；刚才；确实，真正地；非常；勉强地','/d͡ʒʌst/','/d͡ʒʌst/','adjective','["It is a just assessment of the facts.","It looks like a just solution at first glance.","He calls it vermilion,but it''s just red to me."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('human','adj.人的；人性的；有人情味的，有人性的n.人','/ˈhjuː.mən/','/ˈ(h)ju.mən/','noun','["Humans share common ancestors with other apes.","To err is human; to forgive,divine."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notice','v.注意到，察觉到n.注意，察觉；通知，布告','/ˈnəʊtɪs/','/ˈnoʊtɪs/','noun','["He took no notice of the changes,and went on as though nothing had happened.","I always read the death notices in the paper.","The sidewalk adjacent to the damaged bridge stonework shall be closed until further notice."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('owner','n.物主，所有人','/ˈəʊnə/','/ˈoʊnɚ/','noun','["The police recovered the stolen car and returned it to its owner."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hometown','adj.家乡的n.家乡','','','noun','["hometown decision,hometown verdict"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('relax','v.放松，松弛；放宽，缓和','/ɹɪˈlæks/','/ɹɪˈlæks/','verb','["to relax a rope or cord","to relax discipline","Amusement relaxes the mind."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('custom','n.习惯，风俗；惯例；','/ˈkʌstəm/','/ˈkʌstəm/','noun','["The Ancient Egyptian culture had many distinctive and interesting beliefs and customs.","My feet are very large,so I need custom shoes.","We can embroider a wide range of ready designs or a custom logo."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permission','n.许可，允许','/pəˈmɪʃən/','/pɚˈmɪʃən/','noun','["Sire,do I have your permission to execute this traitor?","I used the \"chmod\" command to change the file''s permission."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('home','adj.家庭的；家用的；国内的n.家乡；家，家庭；原产地，发源地','/(h)əʊm/','/hoʊm/','noun','["the home of the pine","The dog homed.","The missile was able to home in on the target."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hole','n.洞，孔眼；漏洞，缺陷','/həʊl/','/hoʊl/','noun','["There’s a hole in my shoe.  Her stocking has a hole in it.","I have found a hole in your argument.","car hole;  brain hole"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('print','v.印刷，出版；用印刷体写；冲洗','/pɹɪnt/','/pɹɪnt/','noun','["TV and the internet haven''t killed print.","Write in print using block letters.","The print is too small for me to read."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('material','adj.物质的，实际的；客观存在的；重要的n.材料，原料；素材；布料','/məˈtɪəɹɪəl/','/məˈtɪɹi.əl/','noun','["Asphalt,composed of oil and sand,is a widely used material for roads.","We were a warm-up act at the time; we didn''t have enough original material to headline.","You''ll need about a yard of material to make this."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('although','conj.虽然，尽管；然而','/ɔːlˈðəʊ/','/ɑlˈðoʊ/','conjunction','["Although it was very muddy,the football game went on.","It was difficult,although not as difficult as we had expected."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beach','n.海滩，沙滩','/biːt͡ʃ/','/bit͡ʃ/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('baby','n.婴儿','/ˈbeɪbi/','/ˈbeɪbi/','noun','["When is your baby due?","Stand up for yourself – don''t be such a baby!","I only qualified as an architect this summer,so I''m still a baby."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('iron','v.熨，烫n.铁；烙铁，熨斗','/ˈaɪən/','/ˈaɪɚn/','noun','["wrought iron,ductile iron,cast iron,pig iron,gray iron","He appeared easygoing,but inside he was pure iron.","He lifts iron on the weekends."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adverb','n.副词','/ˈæd.vɜːb/','/ˈæd.vɝb/','noun','["I often went outside hiking during my stay in Japan."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('president','n.总统；主席；校长，会长；董事长，总经理','/ˈpɹɛzɨdənt/','/ˈpɹɛzɨdənt/','noun','["The vast majority of presidents have been male."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explain','v.讲解，说明','/ɛkˈspleɪn/','/ɛkˈspleɪn/','verb','["To explain a chapter of the Bible."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hum','v.[hummed-hummed,humming]哼曲子；发出嗡嗡声；忙碌，充满活力','/ˈhʌm/','/ˈhʌm/','interjection','["Hmm... I just can''t decide between the two.","Just where were you until 2 a.m.? Hmm?","They could hear a hum coming from the kitchen,and found the dishwasher on."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('basket','n.篮，篓，筐','/ˈbaːskət/','/ˈbæskɪt/','noun','["A basket of fake fruit adorned the table.","The point guard drove toward the basket.","The last-second basket sealed the victory."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lunch','n.午餐','/lʌnt͡ʃ/','/lʌnt͡ʃ/','noun','["After the funeral there was a lunch for those who didn''t go to the cemetery.","I like to lunch in Italian restaurants."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hope','n&v.希望，期望','/həʊp/','/hoʊp/','verb','["I am still hoping that all will turn out well.","I hope you all the best."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thirteenth','num.第十三n.十三分之一','/ˌθɜːˈtiːnθ/','/ˌθɝˈtiːnθ/','noun','[]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attempt','n&v.尝试，企图；努力','/əˈtɛmpt/','/əˈtɛmpt/','noun','["It was worth the attempt.","1584 No man can charge us of any attempt against the realm. (Allen''s Defence Of English Catholics,cited after Edinburgh review 1883,p. 378)","A group of 80 budding mountaineers attempted Kilimanjaro,but 30 of them didn''t make it to the top."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thick','adj.厚的，粗的；笨的，迟钝的；稠的，浓的；密的，密集的','/θɪk/','/θɪk/','noun','["It was mayhem in the thick of battle.","I want some planks that are two inches thick.","He had such a thick neck that he had to turn his body to look to the side."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('soon','adv.不久，即刻；早，快','/suːn/','/suːn/','adjective','["I need the soonest date you have available."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('belt','n.地带，地区；腰带，皮带',NULL,'/bɛlt/','noun','["As part of the act,the fat clown''s belt broke,causing his pants to fall down.","Keep your belt fastened; this is going to be quite a bumpy ride.","The motor had a single belt that snaked its way back and forth around a variety of wheels."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chop','v.切，劈，砍n.〔羊、猪等〕排骨','/tʃɒp/',NULL,'noun','["I only like lamb chops with mint jelly.","It should take just one good chop to fell the sapling.","A karate chop."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cream','adj.奶油色的n.奶油；护肤霜；奶油色',NULL,'/kɹiːm/','noun','["Take 100 ml of cream and 50 grams of sugar…","the cream of the crop;  the cream of a collection of books or pictures","You look really sunburnt; you should apply some cream."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sense','v.觉得，意识到n.感官，官能；感觉；判断力，见识','/sɛn(t)s/','/sɛns/','noun','["a sense of security","It''s common sense not to put metal objects in a microwave oven.","You don’t make any sense."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bell','n.钟，铃；钟声，铃声',NULL,'/bɛl/','noun','["I’ll give you a bell later.","Who will bell the cat?","to bell a tube"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heavy','adj.重的，重型的；大量的，密集的；严重的，严厉的；剧烈的，繁重的；沉重','/ˈhe.vi/','/ˈhɛ.vi/','noun','["With his wrinkled,uneven face,the actor always seemed to play the heavy in films.","A fight started outside the bar but the heavies came out and stopped it.","The union was well known for the methods it used to heavy many businesses."]');
