INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illness','n.病，疾病','/ˈɪl.nəs/','/ˈɪl.nəs/','noun','["Her grandmother had passed away after a long illness.","Many working days this year have been lost through illness."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('twenty','num.二十，二十个','/ˈtwɛnti/','/ˈtwɛni/','noun','["The waiter’s face lit up when I gave him a twenty.","What’s your twenty,good buddy?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cigarette','n.香烟','/sɪ.ɡəˈɹɛt/','/sɪ.ɡəˈɹɛt/','noun','["Could someone cigarette me?"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('may','modalverb.可能，也许n.山楂花',NULL,'/meɪ/','verb','["you may smoke outside;  may I sit there?","he may be lying;  Schrödinger''s cat may or may not be in the box","may you win;  may the weather be sunny"]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forward','adv.向前；向将来，从今往后adj.前部的，位于前面的','/ˈfoːwəd/','/ˈfɔɹ.wɚd/','noun','["I''ll be glad to forward your mail to you while you''re gone.","The fire was confined to the forward portion of the store.","The stock price is currently 12 times forward earnings."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('could','modalverb.能，会，可以〔can的过去式〕','/kʊd/','/kəd/','verb','["She can speak English,French,and German.   I can play football.   Can you remember your fifth birthday?","You can go outside and play when you''re finished with your homework.   Can I use your pen?","Animals can experience emotions."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('health','n.健康；卫生，保健','/hɛlθ/','/hɛlθ/','noun','["Her mental health is really affected by stressful environments.","The directors are concerned about the financial health of the project.","The enemies on this level have a lot of health."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('positive','adj.积极的，正面的；肯定的；【电】正的，阳性的；确实的，明确的；十足的，','/ˈpɒzɪ̈tɪv/','/ˈpɑzɪ̈tɪv/','noun','["I’m absolutely positive you''ve spelt that wrong.","‘Better’ is an irregular comparative of the positive form ‘good’.","The idea of beauty is not positive,but depends on the different tastes of individuals."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('menu','n.菜单',NULL,'/ˈmɛnju/','noun',NULL);
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('machine','n.机器，机械',NULL,'/məˈʃin/','noun','["I called you earlier,but all I got was the machine.","Game developers assume they''re pushing the limits of the machine.","Bruce Campbell was a \"demon-killing machine\" because he made quick work of killing demons."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('able','adj.能够…的，得以…的；有才干的，能力出',NULL,'/ˈeɪ.bl̩/','adjective','["I’ll see you as soon as I’m able.","After the past week of forced marches,only half the men are fully able.","He was born to an able family."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('evening','n.傍晚，晚上',NULL,'/ˈivnɪŋ/','noun','["It was the evening of the Roman Empire."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mend','v.修理，修补；改良，改进；修正，改正；恢复健康，痊愈','/mɛnd/',NULL,'noun','["My trousers have a big rip in them and need a mend.","My trousers have a big rip in them and need mending.","Her stutter was mended by a speech therapist."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('return','v.返回，回来；回复，回应；退回；回报n.返回，回来；偿还，归还；恢复；回','/ɹɪˈtɜːn/','/ɹɪˈtɝn/','noun','["I expect the house to be spotless upon my return.","Do you want a one-way or a return?","Last year there were 250 returns of this product,an improvement on the 500 returns the year before."]');
