INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('those','pron.那些','ðoʊz','ðəʊz','pron.','["He went home,and after that I never saw him again.","They''re getting divorced. What do you think about that?","The water is so cold! — That it is."]');
INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worry','v.担心，发愁；困扰，折磨n.担心，发愁，忧虑','ˈwʌɹi','ˈwɒɹi','n.','["I''m afflicted by worry throughout the night.","My main worry is that I''ll miss the train.","Stop worrying about your test,it’ll be fine."]');
