INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('town','n.镇，市镇；市区，市中心','taʊn','taʊn','n.','["This town is really dangerous because these youngsters have Beretta handguns.","I''ll be in Yonkers,then I''m driving into town to see the Knicks at the Garden tonight.","Call me when you get to town."]');
