INSERT INTO junior (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('or','conj.或，或者，还是；即，或者说；否则，要不然','ɔɹ','ɔː(ɹ)','conj.','["He might get cancer,or be hit by a bus,or God knows what.","It''s raining! Come inside or you''ll catch a cold!","The country Myanmar,or Burma"]');
